window.HADITH_BOOKS[13] = [{"id": 6866, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 1, "arabic": "عَنْ اَمِیْرِ الْمُؤمِنِیْن اَبِيْ حَفْصٍ عُمَرَ بْنِ الْخَطَّابِ رَضِیَ الله عَنْہ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’اِنَّـمَا الْاَعْمَالُ بِالنِّيَّاتِ وَ اِنَّمَا لِكُلِّ امْرِئٍ مَّا نَوٰى فَمَنْ كَانَتْ هِجْرَتُهٗ اِلَی اللهِ وَرَسُوْلِهٖ فَهِجْرَتُهٗ اِلَى اللهِ وَرَسُوْلِهٖ وَمَنْ كَانَتْ هِجْرَتُهٗ لِدُنْـيَا يُصِيْبُهَا اَوِ امْرَأَةٍ يَّنْكِحُهَا فَهِجْرَتُهٗ اِلٰى مَا هَاجَرَ اِلَيْهِ. ‘‘ (رَوَاهُ اِمَامَا الْمُحَدِّثِيْنَ اَبُوْعَبْدِاللهِ مُحَمَّدِ بْنِ اِسْمَاعِيْلَ بْنِ اِبْرَاهِيْمَ بْنِ الْمُغِيْرَةِ بْنِ بَرْدِزْبَہُ الْبُخَارِیِّ وَاَبُوْ الْحُسَيْنِ مُسْلِمُ بْنُ الْحَجَّاجِ بْنِ مُسْلِمِ الْقُشَیْریُّ النَّيْسَابُوْرِیُّ فِیْ صَحِيْحَيْهِمَا اللَّذَيْنِ هُمَا اَصَحُّ الْكُتُبِ الْمُصَنَّفَةِ)", "urdu": "امیر المؤمنین حضرت سیِّدُنا ابوحفص عُمَر بن خَطّاب رضی الله عنہ بیان کرتے ہیں کہ میں نے رسولُ الله صلّی اللّٰہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ”بےشک اعمال کا دارومدار نیتوں پر ہے اور ہر شخص کے لئے وہی ہے جس کی اس نے نیت کی پس جس کی ہجرت الله پاک اور اس کے رسول صلّی الله علیہ واٰلہٖ وسلّم کی طرف ہو تو اس کی ہجرت الله ورسول ہی کی طرف ہے اور جس کی ہجرت دنیا حاصل کرنےیا کسی عورت سے نکاح کرنے کے لئے ہو تو اس کی ہجرت اسی طرف ہے جس کی طرف اس نے ہجرت کی۔“(بخاری، كتاب الايمان، باب ما جاء ان الاعمال بالنیة والحسبة...الخ، ۱/ ۳۴، حدیث:۵۴۔ مسلم، کتاب الامارة، باب انما الاعمال بالنيات، ص۸۱۳، حدیث:۴۹۲۷، ’’ینکحھا‘‘ بدلہ ’’یتزوجھا‘‘)", "roman": "Ameer-ul-Momineen Hazrat Sayyiduna Abu Hafs Umar bin Khattab RadiyAllahu Anhu bayan karte hain ke main ne Rasoolullah Sallallahu Alaihi Wasallam ko irshad farmate suna: \"Beshak aamaal ka daromadar niyyaton par hai aur har Shakhs ke liye wahi hai jis ki us ne niyyat ki, pas jis ki hijrat Allah Paak aur us ke Rasool Sallallahu Alaihi Wasallam ki taraf ho to us ki hijrat Allah wa Rasool hi ki taraf hai aur jis ki hijrat dunya hasil karne ya kisi Aurat se Nikah karne ke liye ho to us ki hijrat usi taraf hai jis ki taraf us ne hijrat ki.\" (Bukhari, Kitaab-ul-Iman, Baab Ma Jaa Annal A'maala Bin-Niyyati Wal-Hisbah... ilkh, 1/34, Hadees: 54. Muslim, Kitaab-ul-Imarah, Baab Innama al-A'maalu bin-Niyyaat, p. 813, Hadees: 4927, \"Yankihuha\" badle \"Yatazawwajuha\")"}, {"id": 6867, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 2, "arabic": "عَنْ عُمَرَ رَضيَ اللهُ عَنْهُ اَيْضًا قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ اِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيْدُ بَيَاضِ الثِّيَابِ شَدِيْدُ سَوَادِ الشَّعْرِ لَا يُرٰى عَلَيْهِ اَثَرُ السَّفَرِ وَلَا يَعْرِفُهٗ مِنَّا اَحَدٌ حَتّٰى جَلَسَ اِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاَسْنَدَ رُكْبَتَـيْهِ اِلٰى رُكْبَتَـيْهِ وَوَضَعَ كَفَّيْهِ عَلٰى فَخِذَيْهِ وَقَالَ: يَا مُحَمَّدُ اَخْبِرْنِيْ عَنِ الْاِسْلَامِ. فَقَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ :’’اَلْاِسْلَامُ اَنْ تَشْهَدَ اَنْ لَّااِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا رَّسُوْلُ اللهِ وَتُقِيْمَ الصَّلَاةَ وَتُؤْتِيَ الزَّكٰوةَ، وَتَصُوْمَ رَمَضَانَ، وَتَحُجَّ الْبَـيْتَ اِنِ اسْتَطَعْتَ اِلَيْهِ سَبِيْلًا. ‘‘ قَالَ: صَدَقْتَ. فَعَجِبْنَا لَهٗ يَسْاَلُهٗ وَيُصَدِّقُهٗ. قَالَ: فَاَخْبِرْنِيْ عَنِ الْاِيْمَانِ. قَالَ: ’’اَنْ تُؤْمِنَ بِاللهِ وَمَلَآئِكَتِهٖ وَكُتُبِهٖ وَرُسُلِهٖ وَالْيَوْمِ الْاٰخِرِ وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهٖ وَشَرِّهٖ.‘‘ قَالَ: صَدَقْتَ. قَالَ: فَاَخْبِرْنِيْ عَنِ الْاِحْسَانِ. قَالَ: ’’اَنْ تَعْبُدَ اللهَ كَاَنَّكَ تَرَاهُ فَاِنْ لَّمْ تَكُنْ تَرَاهُ فَاِنَّهٗ يَرَاكَ. ‘‘ قَالَ: فَاَخْبِرْنِيْ عَنِ السَّاعَةِ. قَالَ: ’’مَا الْمَسْئُوْلُ عَنْهَا بِاَعْلَمَ مِنَ السَّائِلِ. ‘‘ قَالَ: فَاَخْبِرْنِيْ عَنْ اَمَارَاتِهَا. قَالَ: ’’اَنْ تَلِدَ الْاَمَةُ رَبَّتَهَا وَاَنْ تَـرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُوْنَ فِي الْبُنْيَانِ. ‘‘ ثُمَّ انْـطَلَقَ فَلَبِثْتُ مَلِيًّا ثُمَّ قَالَ: ’’يَا عُمَرُ! اَتَدْرِيْ مَنِ السَّائِلُ؟‘‘ قُلْتُ: اَللهُ وَرَسُوْلُهٗ اَعْلَمُ. قَالَ: ’’فَاِنَّهٗ جِبْرِيْلُ اَتَاكُمْ يُعَلِّمُكُمْ دِيْنَكُمْ.‘‘ (رَوَاهُ مُسْلِم)", "urdu": "حضرت سیِّدُنا عُمَر بن خطاب رضی الله عنہ سے ہی روایت ہے، آپ فرماتے ہیں: ایک دن ہم بارگاہِ رسالت میں حاضر تھے کہ اچانک نہایت سفید لباس اور انتہائی سیاہ بالوں والا ایک شخص حاضر خدمت ہوا، اس پر نہ تو سفر کے آثار دکھائی دے رہے تھے اور نہ ہی ہم میں سے کوئی اسے پہنچانتا تھا۔ وہ حضور نبی کریم صلّی الله علیہ واٰلہٖ وسلّم کے اتنا قریب ہو کر بیٹھ گیا کہ اس نے اپنے گھٹنے آپ کے مبارک گھٹنوں سے ملا دئیے اور اپنے ہاتھ زانوں پر رکھ کر عرض کی: یا رسولَ الله صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے اسلام کے بارے میں بتائیے؟ تو حضور نبی کریم صلّی الله علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اِسلام یہ ہے کہ تم اس بات کی گواہی دو الله پاک کے سوا کوئی عبادت کے لائق نہیں اور محمد صلّی الله علیہ واٰلہٖ وسلّم الله پاک کے رسول ہیں اور نماز قائم کرو، زکوٰۃ دو، رمضان کے روزے رکھو اور استطاعت ہو تو بیْتُ الله کا حج کرو۔‘‘ اس نے کہا: آپ نے سچ فرمایا۔ ہمیں تعجب ہوا کہ سوال بھی کر رہا ہے اور تصدیق بھی ۔ پھر عرض کی: مجھے ایمان کے بارے میں بتائیے؟ ارشاد فرمایا: ’’ایمان یہ ہے کہ تم الله پاک، اس کے فرشتوں، اس کی کتابوں ،اس کے رسولوں، آخرت اور اچھی وبُری تقدیر پر ایمان لاؤ۔‘‘ اس نے کہا: آپ نے سچ فرمایا۔ پھر عرض کی:مجھے احسان کے بارے میں بتائیے؟ آپ نے ارشاد فرمایا: ’’تم الله پاک کی عبادت اس طرح کرو گویا اسے دیکھ رہے ہو اگر تم اسے نہیں دیکھ سکتے تو بےشک وہ تو تمہیں دیکھ ہی رہا ہے ۔‘‘ پھر اس نے عرض کی: مجھے قیامت کے بارے میں بتائیے؟ ارشاد فرمایا: ’’جس سے قیا مت کے بارے میں پوچھا گیا ہے وہ پوچھنے والے سے زیادہ نہیں جانتا۔‘‘ عرض کی: پھر قیامت کی نشانیاں ہی بتا دیجئے۔ ارشاد فرمایا: ’’باندی (غلام عورت) اپنے مالک کو جنے گی اور تم دیکھو گے کہ ننگے پاؤں ،برہنہ جسم،مفلس، بکریاں چَرانے والے بلند و بالا عمارتوں کی تعمیرات میں ایک دوسرے پر فخر کریں گے ۔‘‘ (حضرت سیِّدُنا عمر فاروق اعظم رضی الله عنہ فرماتے ہیں:)پھر وہ شخص چلاگیا، میں کچھ دیر ٹھہرا رہا۔ پھر آپ صلّی الله علیہ واٰلہٖ وسلّم نے مجھ سے ارشاد فرمایا: ’’اے عمر! جانتے ہو وہ سائل کون تھا؟‘‘ میں نے عرض کی: الله پاک اور اس کے رسول صلّی الله علیہ واٰلہٖ وسلّم بہتر جانتے ہیں۔ ارشاد فرمایا: ’’وہ جبرائیل علیہ السَّلام تھے جو تمہیں تمہارا دین سکھانے آئے تھے۔‘‘ (مسلم، كتاب الايمان، باب بيان الايمان والاسلام والاحسان...الخ،ص۳۳، حدیث:۹۳)", "roman": "Hazrat Sayyiduna Umar bin Khattab RadiyAllahu Anhu se hi Riwayat hai, aap farmate hain: Ek din hum baargah-e-risalat mein haazir the ke achanak nihayat sufaid Libaas aur intehayi siyah Baalon wala ek Shakhs haazir-e-khidmat hua, us par na to safar ke aasaar dikhayi de rahe the aur na hi hum mein se koi use pehchanta tha. Woh Huzoor Nabi Kareem Sallallahu Alaihi Wasallam ke itna qareeb ho kar baith gaya ke us ne apne ghutne aap ke mubarak ghutnon se mila diye aur apne hath zaanon par rakh kar arz ki: Ya Rasoolullah Sallallahu Alaihi Wasallam! Mujhe Islam ke baare mein bataiye? To Huzoor Nabi Kareem Sallallahu Alaihi Wasallam ne irshad farmaya: \"Islam yeh hai ke tum is baat ki Gawahi do Allah Paak ke siwa koi ibadat ke laaiq nahi aur Muhammad Sallallahu Alaihi Wasallam Allah Paak ke Rasool hain aur Namaz qaim karo, Zakat do, Ramzan ke roze rakho aur istita'at ho to Baitullah ka Hajj karo.\" Us ne kaha: Aap ne sach farmaya. Humein ta'ajjub hua ke Sawaal bhi kar raha hai aur tasdeeq bhi. Phir arz ki: Mujhe Iman ke baare mein bataiye? Irshad farmaya: \"Iman yeh hai ke tum Allah Paak, us ke farishton, us ki kitabon, us ke rasoolon, aakhirat aur achhi wa buri taqdeer par iman lao.\" Us ne kaha: Aap ne sach farmaya. Phir arz ki: Mujhe Ihsan ke baare mein bataiye? Aap ne irshad farmaya: \"Tum Allah Paak ki ibadat is tarah karo goya use dekh rahe ho, agar tum use nahi dekh sakte to beshak woh to tumhein dekh hi raha hai.\" Phir us ne arz ki: Mujhe Qayamat ke baare mein bataiye? Irshad farmaya: \"Jis se Qayamat ke baare mein poocha gaya hai woh poochne wale se zyada nahi jaanta.\" Arz ki: Phir Qayamat ki nishaniyan hi bata dijiye. Irshad farmaya: \"Baandi (ghulam Aurat) apne maalik ko janegi aur tum dekhoge ke nange paaon, barhana jism, muflis, bakriyan charane wale buland-o-baala imaraton ki ta'meerat mein ek doosre par fakhr karenge.\" (Hazrat Sayyiduna Umar Farooq-e-Azam RadiyAllahu Anhu farmate hain:) Phir woh Shakhs chala gaya, main kuch der thehra raha. Phir aap Sallallahu Alaihi Wasallam ne mujh se irshad farmaya: \"Ae Umar! Jaante ho woh saail kaun tha?\" Main ne arz ki: Allah Paak aur us ke Rasool Sallallahu Alaihi Wasallam behtar jaante hain. Irshad farmaya: \"Woh Jibraeel Alayhis Salam the jo tumhein tumhara deen sikhaane aaye the.\" (Muslim, Kitaab-ul-Iman, Baab Bayan-il-Iman wal-Islam wal-Ihsan... ilkh, p. 33, Hadees: 93)"}, {"id": 6868, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 3, "arabic": "عَنْ اَبِيْ عَبْدِ الرَّحْمٰنِ عَبْدِ اللهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ رَضيَ اللهُ عَنْهُ مَا قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’بُنِيَ الْاِسْلَامُ عَلٰى خَمْسٍ: شَهَادَةِ اَنْ لَّااِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا عَبْدُهٗ وَرَسُوْلُهٗ وَ اِقَامِ الصَّلَاةِ وَاِيْتَاءِ الزَّكَاةِ وَحَجِّ الْبَـيْتِ وَصَوْمِ رَمَضَانَ.‘‘ (رَوَاهُ الْبُخَارِي وَمُسْلِم)", "urdu": "حضرت سیِّدُنا ابو عبد الرحمٰن عبد اللہ بن عُمَر رضی اللہ عنہما بیان کرتے ہیں:میں نے رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا کہ ”اِسلام کی بنیاد پانچ چیزوں پر ہے: اس بات کی گواہی دینا کہ اللہ پاک کے سوا کوئی عبادت کے لائق نہیں اور بےشک حضرت محمد صلّی اللہ علیہ واٰلہٖ وسلّم اللہ کے بندے اور رسول ہیں، نماز قائم کرنا، زکوٰۃ دینا، بیْتُ اللہ کا حج کرنا اور رمضان کے روزے رکھنا۔“( بخاری، كتاب الايمان، باب دعائكم ايمانكم، ۱/ ۱۴، حدیث:۸۔ مسلم، کتاب الایمان، باب ارکان الاسلام...الخ، ص ۳۷، حدیث:۱۱۳، بدون ’’سمعت‘‘)", "roman": "Hazrat Sayyiduna Abu Abdur Rahman Abdullah Ibn Umar RadiyAllahu Anhuma bayan karte hain: Main ne Rasool-e-Paak Sallallahu Alaihi Wasallam ko irshad farmate suna ke \"Islam ki buniad paanch cheezon par hai: Is baat ki Gawahi dena ke Allah Paak ke siwa koi ibadat ke laaiq nahi aur beshak Hazrat Muhammad Sallallahu Alaihi Wasallam Allah ke bande aur Rasool hain, Namaz qaim karna, Zakat dena, Baitullah ka Hajj karna aur Ramzan ke roze rakhna.\" (Bukhari, Kitaab-ul-Iman, Baab Dua'ukum Imanukum, 1/14, Hadees: 8. Muslim, Kitaab-ul-Iman, Baab Arkan-il-Islam... ilkh, p. 37, Hadees: 113, bidoon \"Sami'tu\")"}, {"id": 6869, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 4, "arabic": "عَنْ اَبِيْ عَبْدِالرَّحْمٰنِ عَبْدِ اللهِ بْنِ مَسْعُوْدٍ رَضيَ اللهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ الصَّادِقُ الْمَصْدُوْقُ: ’’اِنَّ اَحَدَكُمْ يُجْمَعُ خَلْقُهٗ فِيْ بَطْنِ اُمِّهٖ اَرْبَعِيْنَ يَوْمًا ثُمَّ يَكُوْنُ عَلَقَةً مِّثْلَ ذٰلِكَ ثُمَّ يَكُوْنُ مُضْغَةً مِّثْلَ ذٰلِكَ ثُمَّ يُرْسَلُ الْمَلَكُ فَيَنْفُخُ فِيْهِ الرُّوْحَ وَيُؤْمَرُ بِاَرْبَعِ كَلِمَاتٍ: بِكَتْبِ رِزْقِهٖ وَاَجَلِهٖ وَعَمَلِهٖ وَشَقِيٌّ اَوْ سَعِيْدٌ. فَوَالَّذِيْ لَا اِلٰهَ غَيْرُهٗ اِنَّ اَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ اَهْلِ الْجَنَّةِ حَتّٰى مَا يَكُوْنُ بَيْنَهٗ وَبَيْنَهَا اِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ اَهْلِ النَّارِ فَيَدْخُلُهَا وَاِنَّ اَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ اَهْلِ النَّارِ حَتّٰى مَا يَكُونُ بَيْنَهٗ وَبَيْنَهَا اِلَّا ذِرَاعٌ فَيَسْبِقُ عَلَيْهِ الْكِتَابُ فَيَعْمَلُ بِعَمَلِ اَهْلِ الْجَنَّةِ فَيَدْخُلُهَا.‘‘ (رَوَاهُ الْبُخَارِی وَمُسْلِمٌ)", "urdu": "ترجمہ:حضرت سیِّدُنا ابو عبدالرحمٰن عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے کہ صادق ومصدوق(یعنی سچے اور تصدیق کئے ہوئے) نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ہم سے بیان فرمایا: ’’تمہاری پیدائش (کے مادہ یعنی نطفہ) کو ماں کے پیٹ میں 40 دن تک جمع کیا جاتا ہے، پھر 40 دن جما ہوا خون، پھر40 دن تک مُضْغَہ (گوشت کے لوتھڑے) کی صورت میں رہتا ہے، پھر اللہ پاک اس کی طرف ایک فرشتہ بھیجتا ہے، وہ اس میں روح پھونکتا ہےاور اسے چارچیزیں لکھنے کا حکم دیتا ہے:اس کا عمل، اس کی موت کا وقت، اس کا رزق اور وہ نیک ہے یا بدبخت۔ پس اس کی قسم جس کے سوا کوئی معبود نہیں! بےشک تم میں سے کوئی جنتیوں جیسے عمل کرتا رہتا ہے یہاں تک کہ جنت اور اس کے درمیان ایک گز کا فاصلہ رہ جاتا ہے پس تقدیراس پر غالب آ جاتی ہے تو وہ جہنمیوں جیسے عمل کر کے جہنم میں داخل ہو جاتا ہے اور بےشک تم میں کوئی جہنمیوں جیسے عمل کرتا رہتا ہے یہاں تک کہ اس کے اور جہنم کے درمیان ایک گز کا فاصلہ رہ جاتا ہے پس تقدیر اس پرغالب آ جاتی ہے اور وہ جنتیوں جیسے عمل کرکے جنت میں داخل ہو جاتا ہے۔‘‘\n(بخاری، کتاب بدء الخلق، باب ذکر الملائکة، ۲/ ۳۸، حدیث:۳۲۰۸، بتغیر قلیل۔مسلم، كتاب القدر، باب کیفیة الخلق الادمی، ص ۱۰۹۰، حدیث:۶۷۲۳)", "roman": "Tarjuma: Hazrat Sayyiduna Abu Abdur Rahman Abdullah Ibn Mas'ood RadiyAllahu Anhu se Marwi hai ke Sadiq-o-Masdooq (yaani sacche aur tasdeeq kiye hue) Nabi Sallallahu Alaihi Wasallam ne hum se bayan farmaya: \"Tumhari paidaaish (ke maaddah yaani nutfah) ko maa ke pait mein 40 din tak jama kiya jata hai, phir 40 din jama hua khoon, phir 40 din tak mudghah (gosht ke lothray) ki soorat mein rehta hai, phir Allah Paak us ki taraf ek farishta bhejta hai, woh us mein rooh phoonkta hai aur use chaar cheezain likhne ka Hukm deta hai: Us ka amal, us ki maut ka waqt, us ka rizq aur woh nek hai ya badbakht. Pas us ki qasam jis ke siwa koi mabood nahi! Beshak tum mein se koi jannatiyon jaise amal karta rehta hai yahan tak ke jannat aur us ke darmiyan ek gaz ka faasla reh jata hai pas taqdeer us par ghalib aa jaati hai to woh jahannamiyon jaise amal kar ke jahannam mein daakhil ho jata hai aur beshak tum mein koi jahannamiyon jaise amal karta rehta hai yahan tak ke us ke aur jahannam ke darmiyan ek gaz ka faasla reh jata hai pas taqdeer us par ghalib aa jaati hai aur woh jannatiyon jaise amal karke jannat mein daakhil ho jata hai.\" (Bukhari, Kitaab Bad'il Khalq, Baab Zikr-il-Malaikah, 2/38, Hadees: 3208, ba-taghayyur-e-qaleel. Muslim, Kitaab-ul-Qadr, Baab Kaifiyyat-e-Khalq-il-Aadami, p. 1090, Hadees: 6723)"}, {"id": 6870, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 5, "arabic": "عَنْ اُمِّ الْمُؤمِنِيْنَ اُمِّ عَبْدِ اللهِ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ رَسُوْلُ اللهِ: ’’مَنْ اَحْدَثَ فِيْ اَمْرِنَا هٰذَا مَا لَيْسَ مِنْهُ فَهُوَ رَدٌّ. ‘‘ (رَوَاهُ الْبُخَارِی وَمُسْلِمٌ) وَفِيْ رِوَايَةٍ لِمُسْلِمٍ: ’’مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ اَمْرُنَا فَهُوَ رَدٌّ.‘‘", "urdu": "اُمِّ عبداللہ اُمُّ المؤمنین حضرت سیِّدَتُنا عائشہ صدیقہ رضی اللہ عنہا فرماتی ہیں کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے اِرشاد فرمایا: ’’ جس نے ہمارے دین میں کوئی ایسی چیز ایجادکی جو ہمارے دین سے نہیں تو وہ مردود ہے۔ ‘‘\n (بخاری، کتاب الصلح، باب اذا اصطلحوا علی صلح جور...الخ، ۲/ ۲۱۱، حدیث:۲۶۹۷، ’’منہ‘‘ بدلہ ’’فیہ‘‘ ۔ مسلم، كتاب الاقضية، باب نقض الاحكام الباطلة...الخ،ص۷۳۱، حدیث:۴۴۹۲)\n مسلم شریف کی ایک روایت میں ہے: ”جس نے کوئی ایسا عمل کیا جوہمارے دین سے نہیں تو اس کا وہ عمل مردود ہے۔‘‘\n(مسلم، كتاب الاقضية، باب نقض الاحكام الباطلة...الخ،ص ۷۳۱، حدیث: ۴۴۹۳)", "roman": "Umm-e-Abdullah Umm-ul-Momineen Hazrat Sayyidatuna Aisha Siddiqah Radiyallahu Anha farmati hain ke Rasool-e-Akram Sallallahu Alaihi Wasallam ne irshad farmaya: \"Jis ne hamare deen mein koi aisi cheez ijaad ki jo hamare deen se nahi to woh mardood hai.\" (Bukhari, Kitaab-us-Sulh, Baab Iza Istalahoo Ala Sulhin Jaور... ilkh, 2/211, Hadees: 2697, \"Minhu\" badle \"Feehi\". Muslim, Kitaab-ul-Aqdiyah, Baab Naqd-il-Ahkam-il-Baatilah... ilkh, p. 731, Hadees: 4492). Muslim shareef ki ek Riwayat mein hai: \"Jis ne koi aisa amal kiya jo hamare deen se nahi to us ka woh amal mardood hai.\" (Muslim, Kitaab-ul-Aqdiyah, Baab Naqd-il-Ahkam-il-Baatilah... ilkh, p. 731, Hadees: 4493)"}, {"id": 6871, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 6, "arabic": "عَنْ اَبِيْ عَبْدِ اللهِ النُّعْمَانِ بْنِ بَشِيْرٍ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ:’’ اِنَّ الْحَلَالَ بَيِّنٌ وَّاِنَّ الْحَرَامَ بَيِّنٌ وَّبَيْنَهُمَا مُشْتَبِهَاتٌ لَّا يَعْلَمُهُنَّ كَثِيْرٌ مِّنَ النَّاسِ فَمَنِ اتَّقَى الشُّبُهَاتِ اِسْتَبْرَاَ لِدِيْـنِهٖ وعِرْضِهٖ وَمَنْ وَّقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ كَالرَّاعِيْ يَرْعٰى حَوْلَ الْحِمٰى يُوشِكُ اَنْ يَرْتَعَ فِيْهِ اَلَا وَاِنَّ لِكُلِّ مَلِكٍ حِمًى. اَلَا وَاِنَّ حِمَى اللهِ مَحَارِمُهٗ اَلَا وَاِنَّ فِي الْجَسَدِ مُضْغَةً اِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهٗ وَاِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهٗ اَلَا وَهِيَ الْقَلْبُ.‘‘ (رَوَاهُ الْبُخَارِی وَمُسْلِمٌ)", "urdu": "حضرت سیِّدُنا نعمان بن بشیر رضی اللہ عنہ بیان کرتے ہیں: میں نے رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سناکہ ’’ بے شک حلال ظاہر ہے اورحرام بھی ظاہرہےاوراُن کے درمیا ن مشکوک چیزیں ہیں جنہیں بہت سے لوگ نہیں جانتے ۔تو جو ان مشکوک چیزوں سے بچا اس نے اپنا دِین اور اپنی عزت محفوظ کرلی اور جوان مشکوک چیزوں میں پڑ ا وہ حرام میں پڑ گیا ۔جیسے وہ چرواہا جو ممنوعہ چراہ گا ہ کے قریب بکریاں چَراتاہو توقریب ہے کہ وہ جانورا س چراہ گاہ میں بھی چرنے لگیں۔ خبردار! ہر بادشا ہ کی ممنوعہ چراہ گاہ ہوتی ہے اور اللہ پاک کی ممنوعہ چراہ گاہ اس کی حرام کردہ اَشیاء ہیں۔خبرادر!جسم میں گوشت کا ایک ٹکڑاہے جب وہ ٹھیک ہوجائے تو سارا جسم ٹھیک ہوجاتا ہے اور اگر وہ خراب ہوجائے تو سا را جسم خراب ہو جاتاہے۔ سنو! وہ ٹکڑا دل ہے۔‘‘ (بخاری، کتاب الایمان، باب فضل من استبرأ لدینہ، ۱/ ۳۳، حدیث:۵۲، بتغیر قلیل ۔ مسلم، كتاب المساقاة، باب اخذ الحلال وترك الشبهات،ص ۶۶۳، حدیث:۴۰۹۴)", "roman": "Hazrat Sayyiduna Nu'man bin Basheer RadiyAllahu Anhu bayan karte hain: Main ne Rasool-e-Paak Sallallahu Alaihi Wasallam ko irshad farmate suna ke \"Beshak Halal zahir hai aur Haram bhi zahir hai aur un ke darmiyan mashkook cheezain hain jinhein bohat se log nahi jaante. To jo un mashkook cheezon se bacha us ne apna deen aur apni izzat mehfooz kar li aur jo un mashkook cheezon mein pada woh Haram mein pad gaya. Jaise woh charwaha jo mamnoo'ah charagah ke qareeb bakriyan charata ho to qareeb hai ke woh janwar us charagah mein bhi charne lagein. Khabardar! Har badshah ki mamnoo'ah charagah hoti hai aur Allah Paak ki mamnoo'ah charagah us ki Haram kardah ashya hain. Khabardar! Jism mein gosht ka ek tukda hai jab woh theek ho jaye to sara jism theek ho jata hai aur agar woh kharab ho jaye to sara jism kharab ho jata hai. Suno! Woh tukda dil hai.\" (Bukhari, Kitaab-ul-Iman, Baab Fazl Man Istabra-a Li-Deenihi, 1/33, Hadees: 52, ba-taghayyur-e-qaleel. Muslim, Kitaab-ul-Musaqaat, Baab Akhz-il-Halal wa Tark-ish-Shubuhaat, p. 663, Hadees: 4094)"}, {"id": 6872, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 7, "arabic": "عَنْ اَبِيْ رُقَيَّةَ تَمِيْمِ بْنِ اَوْسٍ الدَّارِيِّ رَضيَ اللهُ عَنْهُ اَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اَلدِّيْنُ النَّصِيْحَةُ.‘‘ قُلْنَا: لِمَنْ؟ قَالَ: ’’لِلّٰهِ وَلِكِتَابِهٖ وَلِرَسُوْلِهٖ وَلِاَئِمَّةِ الْمُسْلِمِيْنَ وَعَامَّتِهِمْ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابو رقیہ تمیم بن اوس داری رضی اللہ عنہ سے روایت ہے کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’دین خیر خواہی ہے۔‘‘ ہم نے عرض کی: کس کے لئے؟ ارشاد فرمایا: ’’اللہ پاک کےلئے، اس کی کتاب کے لئے، اس کے رسول کے لئے، مسلمانوں کے ائمہ اور عام مسلمانوں کے لئے۔‘‘\n(مسلم، كتاب الایمان، باب بیان ان الدین النصیحة، ص ۵۱، حدیث:۱۹۶)", "roman": "Hazrat Sayyiduna Abu Ruqayyah Tameem bin Aus Daari RadiyAllahu Anhu se Riwayat hai ke Rasool-e-Paak Sallallahu Alaihi Wasallam ne irshad farmaya: \"Deen khair khwahi hai.\" Hum ne arz ki: Kis ke liye? Irshad farmaya: \"Allah Paak ke liye, us ki Kitaab ke liye, us ke Rasool ke liye, Musalmanon ke a'immah aur aam Musalmanon ke liye.\" (Muslim, Kitaab-ul-Iman, Baab Bayan Anna Ad-Deena An-Naseehah, p. 51, Hadees: 196)"}, {"id": 6873, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 8, "arabic": "عَنِ ابْنِ عُمَرَ رَضيَ اللهُ عَنْهُ مَا اَنَّ رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم قَالَ: ’’اُمِرْتُ اَنْ اُقَاتِلَ النَّاسَ حَتّٰى يَشْهَدُوْا اَنْ لَّا اِلٰهَ اِلَّا اللهُ وَاَنَّ مُحَمَّدًا رَسُوْلُ اللهِ وَيُقِيْمُوْا الصَّلَاةَ وَيُؤْتُوْا الزَّكَاةَ فَاِذَا فَعَلُوْا ذٰلِكَ عَصَمُوْا مِنِّيْ دِمَآءَهُمْ وَ اَمْوَالَهُمْ اِلَّا بِحَقِّ الْاِسْلَامِ وَحِسَابُهُمْ عَلَى اللهِ تَعَالٰى.‘‘(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "حضرت سیِّدُنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسولِ پاک صلی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ مجھے حکم دیا گیا ہے کہ میں لوگوں سے جہاد کروں یہاں تک کہ وہ اس بات کی گواہی دیں کہ اللہ پاک کے سوا کوئی عبادت کے لائق نہیں اور یہ کہ محمد ( صلّی اللہ علیہ واٰلہٖ وسلّم ) اللہ پاک کے رسول ہیں، نماز قائم کریں اور زکوٰۃ ادا کریں۔ پس جب انہوں نے یہ کام کرلیا تو انہوں نے مجھ سے اپنا خون اور مال بچالیا سوائے اسلام کے حق کے اور ان کا حساب اللہ پاک کے ذمَّۂ کرم پر ہے۔‘‘(بخاری، كتاب الایمان، باب فان تابوا واقاموا الصلاة، ۱/ ۲۰، حدیث:۲۵۔ مسلم، کتاب الایمان، باب الامر بقتال الناس حتی یقولوا...الخ، ص۴۰، حدیث:۱۲۹)", "roman": "Hazrat Sayyiduna Abdullah Ibn Umar RadiyAllahu Anhuma se Riwayat hai ke Rasool-e-Paak Sallallahu Alaihi Wasallam ne irshad farmaya: \"Mujhe Hukm diya gaya hai ke main logon se jihad karoon yahan tak ke woh is baat ki Gawahi dein ke Allah Paak ke siwa koi ibadat ke laaiq nahi aur yeh ke Muhammad (Sallallahu Alaihi Wasallam) Allah Paak ke Rasool hain, Namaz qaim karein aur Zakat ada karein. Pas jab unhon ne yeh kaam kar liya to unhon ne mujh se apna khoon aur Maal bacha liya siwaye Islam ke haq ke aur un ka hisab Allah Paak ke zimmah-e-karam par hai.\" (Bukhari, Kitaab-ul-Iman, Baab Fa-in Taaboo wa Aqaamoo As-Salah, 1/20, Hadees: 25. Muslim, Kitaab-ul-Iman, Baab Al-Amr bi-Qitaal-in-Naas Hatta Yaqooloo... ilkh, p. 40, Hadees: 129)"}, {"id": 6874, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 9, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ عَبْدِ الرَّحْمٰنِ بْنِ صَخْرٍ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللہ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’ مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوْهُ وَمَا اَمَرْتُكُمْ بِهٖ فَافْعَلُوْا مِنْهُ مَا اسْتَطَعْتُمْ فَاِنَّمَا اَهْلَكَ الَّذِيْنَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَآئِلِہِمْ وَاخْتِلَافُهُمْ عَلٰى اَنْبِيَآئِهِمْ.‘‘( رَوَاهُ الْبُخَارِی وَمُسْلِم )", "urdu": "حضرت سیِّدُنا ابوہریرہ عبد الرحمٰن بن صخر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ’’جس چیز سے میں تمہیں منع کردوں تو اس سے رک جاؤ اور جس چیز کا میں تمہیں حکم دوں تو اپنی استطاعت کے مطابق اس پر عمل کرو کیونکہ تم سے پہلوں کو زیادہ سوال کرنےاور اپنے انبیا کی مخالفت نے ہلاک کردیا۔‘‘(بخاری، کتاب الاعتصام بالکتاب والسنة، باب الاقتداء بسنن رسول، ۴/ ۵۰۲، حدیث: ۷۲۸۸ ، بتغیر قلیل ۔ مسلم، کتاب الحج، باب فی الحج مرة فی العمر،ص۵۳۶، حدیث:۳۲۵۷، بتغیر)", "roman": "Hazrat Sayyiduna Abu Hurairah Abdur Rahman Bin Sakhr RadiyAllahu Anhu bayaan karte hain ke main ne Rasool-e-Paak Sallallahu Alayhi wa Sallam ko irshaad farmate suna: ''Jis cheez se main tumhein mana' kar doon to us se ruk jao aur jis cheez ka main tumhein Hukm doon to apni istita'at ke mutabiq us par amal karo kyonke tum se pehlo'n ko zyada Sawaal karne aur apne Ambiya ki mukhalifat ne halaak kar diya.'' (Bukhari, Kitaab-ul-I'tisaam bil-Kitaab was-Sunnah, Baab-ul-Iqtida bi Sunan-e-Rasool, 4/502, Hadees: 7288, bitaghayyur-e-qaleel. Muslim, Kitaab-ul-Hajj, Baab fil Hajj marratan fil umr, s. 536, Hadees: 3257, bitaghayyur)"}, {"id": 6875, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 10, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’اِنَّ اللهَ تَعَالٰی طَيِّبٌ لَّا يَقْبَلُ اِلَّا طَيِّبًا وَّاِنَّ اللهَ اَمَرَ الْمُؤْمِنِيْنَ بِمَا اَمَرَ بِهِ الْمُرْسَلِيْنَ فَقَالَ تَعَالٰی: ’’ یٰۤاَیُّهَا الرُّسُلُ كُلُوْا مِنَ الطَّیِّبٰتِ وَ اعْمَلُوْا صَالِحًاؕ-... الاٰیة (پ۱۸، المؤمنون:۵۱)‘‘ وَقَالَ تَعَالَى: ’’ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ... الاٰیة (پ۲، البقرة:۱۷۲)‘‘. ثُمَّ ذَكَرَ الرَّجُلَ يُـطِيْلُ السَّفَرَ اَشْعَثَ اَغْبَرَ يَمُدُّ يَدَيْهِ اِلَى السَّمَآءِ يَا رَبِّ يَا رَبِّ! وَمَطْعَمُهٗ حَرَامٌ وَّمَشْرَ بُہٗ حَرَامٌ وَّغُذِيَ بِالْحَرَامِ فَاَنّٰى يُسْتَجَابُ لِذٰلِكَ.‘‘ (رَوَاهُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک طیب ہے اور وہ پاک ہی کو قبول کرتا ہے اور بے شک اللہ پاک نے مؤمنوں کو بھی اسی چیز کا حکم دیا ہے جس چیز کا رسولوں علیہمُ السّلام کو حکم دیا ہے۔ چنانچہ اللہ پاک نے ارشاد فرمایا:\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ (پ ۱۸، المؤمنون:۵۱)\nترجمہ کنزالایمان: اے پیغمبرو پاکیزہ چیزیں کھاؤ اور اچھا کام کرو۔\n ایک اور جگہ ارشاد فرمایا:\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ (پ ۲، البقرة:۱۷۲)\nترجمہ کنزالایمان: اے ایمان والو کھاؤ ہماری دی ہوئی ستھری چیزیں ۔\n پھر آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ایک شخص کا تذکرہ کیا جو طویل سفر کرتا ہے، گرد آلود پراگندا بالوں والا ہے، وہ اپنے ہاتھ آسمان کی طرف پھیلا کر کہتا ہے:اے میرے رب ! اے میرے رب! حالانکہ اسکا کھانا حرام، پینا حرام اور اس کی غذا حرام سے ہے تو اس کی دعا کیسے قبول ہو سکتی ہے۔‘‘(مسلم، كتاب الزکاة، باب قبول الصدقة من الکسب...الخ، ص۳۹۳، حدیث:۲۳۴۶)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu bayaan karte hain ke Huzoor Nabi Kareem Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Beshak Allah Paak tayyib hai aur woh Paak hi ko Qubool karta hai aur beshak Allah Paak ne Momino'n ko bhi usi cheez ka Hukm diya hai jis cheez ka Rasoolon Alayhimus Salam ko Hukm diya hai. Chunanche Allah Paak ne irshaad farmaya:\nيَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ (پ ۱۸، المؤمنون:۵۱)\nTarjuma Kanzul Iman: Aye paighambaro pakeeza cheezein khao aur achha kaam karo.\nEk aur jagah irshaad farmaya:\nيَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُلُواْ مِن طَيِّبَٰتِ مَا رَزَقۡنَٰكُمۡ (پ ۲، البقرة:۱۷۲)\nTarjuma Kanzul Iman: Aye imaan walo khao hamari di hui suthri cheezein.\nPhir Aap Sallallahu Alayhi wa Sallam ne ek Shakhs ka tazkira kiya jo taweel safar karta hai, gard-alood paraganda Baal'on wala hai, woh apne haath aasmaan ki taraf phaila kar kehta hai: Aye mere Rab! Aye mere Rab! halanke uska khana Haram, peena Haram aur uski ghiza Haram se hai to uski Dua kaise Qubool ho sakti hai.'' (Muslim, Kitaab-uz-Zakaat, Baab Qubool-is-Sadaqah minal Kasb...alkh, s. 393, Hadees: 2346)"}, {"id": 6876, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 11, "arabic": "عَنْ اَبِيْ مُحَمَّدِنِ الْحَسَنِ بْنِ عَلِیِّ بْنِ اَبِیْ طَالِبٍ سِبْطِ رَسُوْلِ اللہ وَرَیْحَانَتِہٖ رَضيَ اللهُ عَنْهُ مَا قَالَ: حَفِظْتُ مِنْ رَّسُوْلِ اللہ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’دَعْ مَا یَرِیْبُکَ اِلٰی مَا لَا یَرِیْبُکَ.‘‘(رَوَاهُ التِّرْمِذِیُّ وَالنِّسَائِیُّ. وَقَالَ التِّرْمِذِیُّ حَدِيْثٌ حَسَنٌ صَحِیْحٌ)", "urdu": "خوشبوئے مصطفٰے، جگر گوشَۂ رسول حضرت سیِّدُنا ابو محمد حسن بن علی رضی اللہ عنہما فرماتے ہیں: میں نے رسولُ اللہ صلّی اللہ علیہ وسلّم سے (سن کر)یہ بات یاد کی کہ ’’جو چیز تجھے شک میں ڈالے اسے چھوڑ کر وہ اختیار کر جو تجھے شک میں نہ ڈالے۔‘‘\n(ترمذی، كتاب صفة القیامة والرقائق والورع، ۴/ ۲۳۲، حدیث:۲۵۲۶ ۔ نسائی، کتاب الاشربة، باب الحث علی ترک الشبھات، ص۹۰۰، حدیث:۵۷۲۲)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی اور حضرت سیِّدُنا امام ابو عبدالرحمٰن احمد بن شعیب بن علی خراسانی نسائی رحمۃ اللہ علیہما نے (ترمذی ونسائی میں) روایت کیا ہے اور حضرت سیِّدُنا امام ترمذی رحمۃ اللہ علیہ نے فرمایا: (اصولِ حدیث کی رو سے) یہ حدیث حسن صحیح ہے۔)", "roman": "Khushboo-e-Mustafa, Jigar Gosha-e-Rasool Hazrat Sayyiduna Abu Muhammad Hasan bin Ali RadiyAllahu Anhuma farmate hain: Main ne Rasoolullah Sallallahu Alayhi wa Sallam se (sun kar) yeh baat yaad ki ke ''Jo cheez tujhe shak mein daale use chhor kar woh ikhtiyaar kar jo tujhe shak mein na daale.''\n(Tirmizi, Kitaab Sifat-il-Qiyamah war-Raqaiq wal-Wara', 4/232, Hadees: 2526. Nasai, Kitaab-ul-Ashribah, Baab-ul-Hass ala Tark-ish-Shubuhaat, s. 900, Hadees: 5722)\n(Is Hadees ko Hazrat Sayyiduna Imam Abu Eesa Muhammad bin Eesa Tirmizi aur Hazrat Sayyiduna Imam Abu Abdur Rahman Ahmad bin Shu'ayb bin Ali Khurasani Nasai Rahmatullah Alayhima ne (Tirmizi wa Nasai mein) Riwayat kiya hai aur Hazrat Sayyiduna Imam Tirmizi Rahmatullah Alayh ne farmaya: (Usool-e-Hadees ki roo se) Yeh Hadees Hasan Saheeh hai.)"}, {"id": 6877, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 12, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’مِنْ حُسْنِ اِسْلَامِ الْمَرْءِ تَرْكُهٗ مَا لَا يَعْنِيْهِ.‘‘\n( حَدِيْثٌ حَسَنٌ، رَوَاهُ التِّرْمِذِيُّ وَغَيْرُهٗ ھٰکَذَا)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ آدمی کے اسلام کی خوبی میں سے یہ بھی ہے کہ وہ بے فائدہ کاموں کو چھوڑ دے ۔‘‘\n(ترمذی، كتاب الزھد، باب ماجاء من تکلم بالکلمة لیضحک الناس، ۴/ ۱۴۲، حدیث:۲۳۲۴)\n (یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہ اور دیگر محدثین نے اسی طرح روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu bayaan karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Aadmi ke Islam ki khoobi mein se yeh bhi hai ke woh be-faida kaamon ko chhor de.''\n(Tirmizi, Kitaab-uz-Zuhd, Baab Ma Jaa'a man Takallama bil-Kalimati liyudhika-n-naas, 4/142, Hadees: 2324)\n(Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Eesa Muhammad bin Eesa Tirmizi Rahmatullah Alayh aur deegar Muhaddiseen ne isi tarah Riwayat kiya hai.)"}, {"id": 6878, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 13, "arabic": "عَنْ اَبِيْ حَمْزَةَ اَنَسِ بْنِ مَالِكٍ رَضيَ اللهُ عَنْهُ خَادِمِ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَن النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’لَا يُؤْمِنُ اَحَدُكُمْ حَتّٰى يُحِبَّ لِاَخِيْهِ مَا يُحِبُّ لِنَفْسِهٖ.‘‘(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "خادِمِ رسول ابو حمزہ حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: تم میں سے کوئی اس وقت تک (کامل) ایمان والا نہیں ہوسکتا جب تک کہ اپنے (مسلمان)بھائی کے لئے بھی وہی چیز پسند نہ کرے جووہ اپنے لئے پسند کرتا ہے۔(بخاری، كتاب الايمان، باب من الايمان ان یحب لاخیہ...الخ، ۱/ ۱۶، حدیث:۱۳ ۔ مسلم، کتاب الایمان، باب الدلیل علی ان من خصال الایمان...الخ، ص۴۷، حدیث: ۱۷۰)", "roman": "Khaadim-e-Rasool Abu Hamza Hazrat Sayyiduna Anas Bin Malik RadiyAllahu Anhu se Riwayat hai ke Huzoor Nabi Paak Sallallahu Alayhi wa Sallam ne irshaad farmaya: Tum mein se koi us waqt tak (kaamil) imaan wala nahi ho sakta jab tak ke apne (Musalman) bhai ke liye bhi wahi cheez pasand na kare jo woh apne liye pasand karta hai. (Bukhari, Kitaab-ul-Imaan, Baab minal Imaani an yuhibba li akheehi...alkh, 1/16, Hadees: 13. Muslim, Kitaab-ul-Imaan, Baab-ud-Daleel ala anna min Khisaal-il-Imaan...alkh, s. 47, Hadees: 170)"}, {"id": 6879, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 14, "arabic": "عَنِ ابْنِ مَسْعُوْدٍ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ سُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’لَا یَحِلُّ دَمُ امْرِیٍٔ مُّسْلِـمٍ اِلَّا بِاِحْدٰی ثَلَاثٍ اَلثَّیِّبِ الزَّانِی وَالنَّفْسِ بِالنَّفْسِ وَالتَّارِکِ لِدِیْنِہِ الْمُفَارِقِ لِلْجَمَاعَۃ. ‘‘(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "حضرت سیِّدُنا ابن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسولِ پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’کسی مسلمان شخص کا خون حلال نہیں سوائے یہ کہ تین میں سے کوئی ایک وجہ پائی جائے: (1)…شادی شدہ زانی، (2)… جان کے بدلے جان (قصاص) اور (3)… اپنے دین کوچھوڑ کرجماعت سے الگ ہونے والا۔‘‘ (بخاری، كتاب الديات، باب قول اللّٰہ تعالٰى: ان النفس بالنفس...الخ، ۴/ ۳۶۱، حدیث:۶۸۷۸ ۔ مسلم، کتاب القسامة، باب ما یباح بہ دم المسلم، ص۷۱۰، حدیث:۴۳۷۵)", "roman": "Hazrat Sayyiduna Ibn Mas'ood RadiyAllahu Anhu bayaan karte hain ke Rasool-e-Paak Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Kisi Musalman Shakhs ka khoon Halal nahi siwaye yeh ke teen mein se koi ek wajah payi jaye: (1)… Shaadi shuda zaani, (2)… Jaan ke badle jaan (qisaas) aur (3)… Apne deen ko chhor kar Jama'at se alag hone wala.'' (Bukhari, Kitaab-ud-Diyaat, Baab Qaul-illahi Ta'ala: Innan-Nafsa bin-Nafs...alkh, 4/361, Hadees: 6878. Muslim, Kitaab-ul-Qasaamah, Baab maa yubaahu bihi Damm-ul-Muslim, s. 710, Hadees: 4375)"}, {"id": 6880, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 15, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْاٰخِرِ فَلْيَقُلْ خَيْرًا اَوْ لِيَصْمُتْ وَمَنْ كَانَ يُؤمِنُ بِاللهِ وَالْيَوْمِ الْاٰخِرِ فَلْيُكْرِمْ جَارَهٗ ومَنْ كَانَ يُؤْمِنُ بِاللهِ والْيَوْمِ الْاٰخِرِ فَلْيُكْرِمْ ضَيْفَهٗ. ‘‘ \n(رَوَاہُ الْبُخَارِی وَمُسْلِم)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہے اسے چاہئے کہ اچھی بات کہے یا خاموش رہےاور جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہے اسے چاہئے کہ اپنے پڑوسی کی عزت کرے اور جو شخص اللہ پاک اور قیامت کے دن پر ایمان رکھتا ہےاسے چاہئے کہ اپنےمہمان کا احترام کرے۔‘‘(بخاری، كتاب الادب، باب من كان يؤمن باللّٰہ ...الخ، ۴/ ۱۰۵،حدیث:۶۰۱۸ ۔ مسلم، کتاب الایمان، باب الحث علی اکرام الجار...الخ، ص۴۸، حدیث:۱۷۳)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu se Marwi hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Jo Shakhs Allah Paak aur Qiyamat ke din par imaan rakhta hai use chahiye ke achhi baat kahe ya khamosh rahe aur jo Shakhs Allah Paak aur Qiyamat ke din par imaan rakhta hai use chahiye ke apne padosi ki izzat kare aur jo Shakhs Allah Paak aur Qiyamat ke din par imaan rakhta hai use chahiye ke apne mehmaan ka ehtiram kare.'' (Bukhari, Kitaab-ul-Adab, Baab man kaana yu'minu billah...alkh, 4/105, Hadees: 6018. Muslim, Kitaab-ul-Imaan, Baab-ul-Hass ala Ikraam-il-Jaar...alkh, s. 48, Hadees: 173)"}, {"id": 6881, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 16, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ اَنَّ رَجُلًا قَالَ لِلنَّبيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : اَوْصِنِيْ. قَالَ: ’’لَاتَغْضَبْ.‘‘ فَرَدَّدَ مِرَارًا. قَالَ: ’’لَاتَغْضَبْ.‘‘\n (رَوَاہُ الْبُخَارِی)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم کی خدمت میں عرض کی: مجھے نصیحت کیجئے۔ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’غصہ نہ کیا کرو۔‘‘ اس نے کئی بار یہی عرض کی تو آپ نے (وہی)ارشاد فرمایا کہ ’’غصہ نہ کیا کرو۔‘‘ (بخاری، كتاب الادب، باب الحذر من الغضب، ۴/ ۱۳۱، حدیث:۶۱۱۶)", "roman": "Hazrat Sayyiduna Abu Hurairah RadiyAllahu Anhu se Marwi hai ke ek Shakhs ne Rasool-e-Kareem Sallallahu Alayhi wa Sallam ki khidmat mein arz ki: Mujhe naseehat kijiye. Aap Sallallahu Alayhi wa Sallam ne irshaad farmaya: ''Gussa na kiya karo.'' Us ne kayi baar yahi arz ki to Aap ne (wahi) irshaad farmaya ke ''Gussa na kiya karo.'' (Bukhari, Kitaab-ul-Adab, Baab-ul-Hazar minal Ghadab, 4/131, Hadees: 6116)"}, {"id": 6882, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 17, "arabic": "عَنْ اَبِيْ يَعْلٰى شَدَّادِ بْنِ اَوْسٍ رَضِیَ اللهُ عَنْہُ عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اِنَّ اللهَ كَتَبَ الْاِحْسَانَ عَلٰى كُلِّ شَيْءٍ. فَاِذَا قَتَلْتُمْ فَاَحْسِنُوا الْقِتْلَةَ وَاِذَا ذَبَحْتُمْ فَاَحْسِنُوا الذِّبْحَةَ وَلْيُحِدَّ اَحَدُكُمْ شَفْرَتَهٗ وَلْيُرِحْ ذَبِيْحَتَهٗ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابویعلی شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسولِ کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک نے ہر چیز کے ساتھ بھلائی کرنا فرض کیا ہے، لہٰذا جب تم قتل کرو تو اچھے طریقے سے قتل کرو اور جب تم ذبح کرو تو اچھے طریقے سے ذبح کرو، تم اپنی چھری کو تیز کرو اور ذبح ہونے والے جانور کو آرام پہنچاؤ۔‘‘ \n( مسلم، كتاب الصيد والذبائح...الخ، باب الامر باحسان الذبح والقتل وتحديد الشفرة، ص۸۳۲، حدیث:۵۰۵۵)", "roman": "Hazrat Sayyiduna Abu Ya'la Shaddad Bin Aws RadiyAllahu Anhu se Riwayat hai ke Rasool-e-Kareem Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Beshak Allah Paak ne har cheez ke saath bhalai karna Farz kiya hai, lihaza jab tum qatl karo to achhe tareeqe se qatl karo aur jab tum Zibah karo to achhe tareeqe se Zibah karo, tum apni chhuri ko teiz karo aur Zibah hone wale jaanwar ko aaram pohanchao.''\n(Muslim, Kitab-us-Sayd waz-Zaba'ih...al-aakhir, Baab-ul-Amr bi-Ihsaniz-Zibah wal-Qatl wa Tahdeed-ish-Shafrah, Safha 832, Hadees: 5055)"}, {"id": 6883, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 18, "arabic": "عَنْ اَبِيْ ذَرٍّ جُنْدُبِ بْنِ جُنَادَةَ وَاَبِيْ عَبْدِ الرَّحْمٰنِ مُعَاذِ بْنِ جَبَلٍ رَضيَ اللهُ عَنْهُ مَا عَنْ رَسُوْلِ اللهِ صَلَّی اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اِتَّقِ اللهَ حَيْثُمَا كُنْتَ وَاتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا وَخَالِـقِ النَّاسَ بِخُلُقٍ حَسَنٍ. (رَوَاہُ التِّرْمِذِیُّ وَقَالَ: حَدِیْثٌ حَسَنٌ وَفِیْ بَعْضِ النُّسَخِ: حَسَنٌ صَحِیْحٌ)", "urdu": "حضرت سیِّدُنا ابو ذر جُندُب بن جُنادہ اورحضرت سیِّدُنا ابو عبد الرحمٰن معاذبن جبل رضی اللہ عنہما سے روایت ہے کہ رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جہاں بھی ہو اللہ پاک سے ڈرتے رہو اور گناہ ہوجائے تو اس کے بعد نیکی کر لیا کرو کہ نیکی گناہ کو مٹا دے گی اور لوگوں کے ساتھ اچھے اخلاق سے ملو۔‘‘ \n(ترمذی، كتاب البرّ والصلة، باب ما جاء فی معاشرة الناس، ۳/ ۳۹۷، حدیث:۱۹۹۴)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہ نے روایت کیا اور فرمایا: یہ حدیث حسن ہے۔ جبکہ بعض نسخوں میں ہے: یہ حدیث حسن صحیح ہے۔)", "roman": "Hazrat Sayyiduna Abu Zar Jundub Bin Junadah aur Hazrat Sayyiduna Abu Abdur Rahman Mu'az Bin Jabal RadiyAllahu Anhuma se Riwayat hai ke Rasool-e-Akram Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Jahan bhi ho Allah Paak se darte raho aur gunah ho jaye to us ke baad neki kar liya karo ke neki gunah ko mita degi aur logon ke saath achhe akhlaaq se milo.''\n(Tirmizi, Kitab-ul-Birr was-Silah, Baab Ma Jaa Fee Mu'asharat-in-Naas, 3/397, Hadees: 1994)\n(Is Hadees ko Hazrat Sayyiduna Imam Abu Isa Muhammad Bin Isa Tirmizi Rahmatullah Alayh ne Riwayat kiya aur farmaya: Yeh Hadees Hasan hai. Jabke baaz nuskho mein hai: Yeh Hadees Hasan Saheeh hai.)"}, {"id": 6884, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 19, "arabic": "عَنْ اَبِي الْعَبَّاسِ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضيَ اللهُ عَنْهُ مَا قَالَ: كُنْتُ خَلْفَ النَّبِیِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فَقَالَ: ’’يَا غُلاَمُ اِنِّيْ اُعَلِّمُكَ كَلِمَاتٍ اِحْفَظِ اللهَ يَحْفَظْكَ، اِحْفَظِ اللهَ تَجِدْهُ تُجَاهَكَ، اِذَا سَاَلْتَ فَاسْاَلِ اللهَ وَاِذَا اسْتَعَنْتَ فَاسْتَعِنْ بِاللهِ وَاعْلَمْ اَنَّ الْاُمَّةَ لَوِ اجْتَمَعَتْ عَلٰى اَنْ يَّنْفَعُوْكَ بِشَيْءٍ لَّمْ يَنْفَعُوْكَ اِلَّا بِشَيْءٍ قَدْ كَتَـبَهُ اللهُ لَكَ واِنِ اجْتَمَعُوْا عَلٰى اَنْ يَّضُرُّوْكَ بِشَيْءٍ لَّمْ يَضُرُّوْكَ اِلَّا بِشَيْءٍ قَدْ كَتَبَهُ اللهُ عَلَيْكَ، رُفِعَتِ الْاَقْلَامُ وَجَفَّتِ الصُّحُفُ.‘‘ (رَوَاہُ التِّرْمِذِیُّ وَقَالَ: حَدِیْثٌ حَسَنٌ صَحِیْحٌ) وَفِيْ رِوَايَةِ غَيْرِ التِّرْمِذِيِّ: ’’اِحْفَظِ اللهَ تَجِدْهُ اَمَامَكَ، تَعَرَّفْ اِلَى اللهِ فِي الرَّخَآءِ يَعرِفْكَ فِي الشِّدَّةِ وَاعْلَمْ اَنَّ مَا اَخْطَاَكَ لَمْ يَكُنْ لِّيُصِيْبَكَ وَمَا اَصَابَكَ لَمْ يَكُنْ لِّيُخْطِئَكَ وَاعْلَمْ اَنَّ النَّصْرَ مَعَ الصَّبْرِ وَاَنَّ الْفَرَجَ مَعَ الْكَرْبِ وَاَنَّ مَعَ الْعُسْرِ يُسْرًا.‘‘", "urdu": "حضرت سیِّد نا عبد اللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں ایک دن حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم کے پیچھے (سواری پر سوار) تھا۔ آپ نے ارشاد فرمایا: ’’اے لڑکے! میں تجھے چند کلمات سکھاتا ہوں ، اللہ پاک کے احکام کی پابندی کر، اللہ پاک تیری حفاظت فرمائے گا، اللہ پاک کے حق کی رعایت کرتو اُسے اپنے سامنے پائے گا، جب مانگے تو اللہ پاک سے ہی مانگ اور جب مدد طلب کرے تو اللہ پاک سے ہی مددطلب کر اور جان لے کہ اگر ساری امت بھی تجھے نفع پہنچانے پر جمع ہو جائے تو صرف اتنا ہی نفع دے گی جتنا اللہ پاک نے تیرے لئے لکھ دیا ہے اور اگر سب مل کر تجھے کوئی نقصان پہنچانا چاہیں تو صرف اتنا ہی پہنچا سکیں گے جتنا اللہ پاک نے تیرے لئے لکھ دیا ہے۔ قلم اُٹھا دئیے گئے اور صحیفے خشک ہوگئے۔‘‘(ترمذی، كتاب صفة القيامة والرقائق والورع، ۴/ ۲۳۱، حدیث:۲۵۲۴)\nترمذی شریف کے علاوہ دیگر کتب میں یوں ہے: ’’اللہ پاک کے حقوق کی حفاظت کر! تو اُسے اپنے قریب پائے گا، خوشحالی میں اللہ پاک کو یاد رکھ وہ تنگدستی میں تجھ پر خاص توجہ فرمائے گا اور جان لے کہ جو تجھے نہیں ملا وہ ملنے والا ہی نہ تھا اور جو مل گیا وہ ٹلنے والا ہی نہ تھا۔جان لے!مدد صبر کے ساتھ اور کُشادگی رَنج وغم کے ساتھ ہے اور تنگی کے ساتھ آسانی ہے۔‘‘ \n(مستدرك، كتاب معرفة الصحابة، باب تعليم النبی ابن عباس، ۴/ ۶۹۹، حدیث: ۶۳۵۸، بتقدم وتاخر)", "roman": "Hazrat Sayyiduna Abdullah Bin Abbas RadiyAllahu Anhuma bayan karte hain ke main ek din Huzoor Nabi-e-Kareem Sallallahu Alayhi wa Sallam ke peeche (sawari par sawaar) tha. Aap ne irshad farmaya: ''Ae larke! Main tujhe chand kalimaat sikhata hoon, Allah Paak ke ahkaam ki pabandi kar, Allah Paak teri hifazat farmaye ga, Allah Paak ke haq ki ri'ayat kar to usey apne saamne paye ga, jab maange to Allah Paak se hi maang aur jab madad talab kare to Allah Paak se hi madad talab kar aur jaan le ke agar Saari ummat bhi tujhe nafa pohanchane par jama ho jaye to Sarf itna hi nafa degi jitna Allah Paak ne tere liye likh diya hai aur agar sab mil kar tujhe koi nuqsan pohanchana chahein to Sarf itna hi pohancha sakein ge jitna Allah Paak ne tere liye likh diya hai. Qalam utha diye gaye aur saheefe khushk ho gaye.''(Tirmizi, Kitab Sifat-il-Qiyamah war-Raqaiq wal-Wara', 4/231, Hadees: 2524)\nTirmizi Shareef ke ilawah deegar kutub mein yoon hai: ''Allah Paak ke huqooq ki hifazat kar! Tu usey apne qareeb paye ga, khush-haali mein Allah Paak ko yaad rakh woh tangdasti mein tujh par khaas tawajjuh farmaye ga aur jaan le ke jo tujhe nahin mila woh milne wala hi na tha aur jo mil gaya woh talne wala hi na tha. Jaan le! Madad sabr ke saath aur kushadgi ranj-o-gham ke saath hai aur tangi ke saath aasani hai.''\n(Mustadrak, Kitab Ma'rifat-is-Sahabah, Baab Ta'leem-in-Nabi Ibn Abbas, 4/699, Hadees: 6358, bi-taqaddum wa ta'akhkhur)"}, {"id": 6885, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 20, "arabic": "عَنْ اَبِيْ مَسْعُوْدٍ عُقْبَةَ بْنِ عَمْرِو الْاَنْصَارِيِّ الْبَدْرِيِّ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’اِنَّ مِمَّا اَدرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْاُوْلٰى اِذَا لَمْ تَستَحِيْ فَاصْنَعْ مَا شِئْتَ.‘‘ (رَوَاہُ البُخَارِی)", "urdu": "بدری صحابی حضرت سیِّدُنا ابومسعود عقبہ بن عَمْرو انصاری رضی اللہ عنہ بیان کرتے ہیں کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا:’’بےشک گزشتہ انبیائے کرام علیہمُ السّلام کے کلام میں سے لوگوں نے یہ بھی پایا ہےکہ جب تمہیں حیا نہ ہو تو جو چاہو کرو۔‘‘ (بخاری كتاب الادب، باب اذا لم تستح فاصنع ما شئت، ۴/ ۱۳۱، حدیث:۶۱۲۰)", "roman": "Badri Sahabi Hazrat Sayyiduna Abu Mas'ood Uqbah Bin Amr Ansari RadiyAllahu Anhu bayan karte hain ke Allah Paak ke Aakhiri Nabi, Muhammad-e-Arabi Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Beshak guzashtah Ambiya-e-Kiram Alaihimus Salam ke kalaam mein se logon ne yeh bhi paya hai ke jab tumhein Haya na ho to jo chaho karo.''(Bukhari, Kitab-ul-Adab, Baab Iza Lam Tastahi Fasna' Ma Shi'ta, 4/131, Hadees: 6120)"}, {"id": 6886, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 21, "arabic": "عَنِ اَبِيْ عَمْرٍو وَقِيْلَ اَبِيْ عَمْرَةَ سُفْيَانَ بْنِ عَبْدِ اللهِ الثَّقَفِيِّ رَضيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَارَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ! قُلْ لِيْ فِي الْاِسْلَامِ قَوْلًا لَا اَسْاَلُ عَنْهُ اَحَدًا غَيْرَكَ. قَالَ: ’’قُلْ اٰمَنْتُ باللهِ ثُمَّ اسْتَقِمْ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابو عمرو یا ابوعمرہ سفیان بن عبداللہ ثقفی رضی اللہ عنہ کہتے ہیں کہ میں نے بارگاہِ رسالت میں عرض کی:یارسولَ اللہ صلّی اللہ علیہ وسلّم ! مجھے اسلام کے بارے میں ایسی بات بتائیے کہ میں اس کے بارے میں آپ کے علاوہ کسی سے نہ پوچھوں۔ تو آپ نے ارشاد فرمایا: ’’کہو میں اللہ پاک پر ایمان لایا پھر اس پر ثابت قدم رہو۔‘‘ \n(مسلم، كتاب الايمان، باب جامع اوصاف الاسلام، ص۴۸، حدیث: ۱۵۹)", "roman": "Hazrat Sayyiduna Abu Amr ya Abu Amrah Sufyan Bin Abdullah Saqafi RadiyAllahu Anhu kehte hain ke main ne Baargah-e-Risalat mein arz ki: Ya Rasoolullah Sallallahu Alayhi wa Sallam! Mujhe Islam ke baare mein aisi baat bataiye ke main is ke baare mein Aap ke ilawah kisi se na poochhoon. To Aap ne irshad farmaya: ''Kaho main Allah Paak par imaan laya phir is par sabit qadam raho.''\n(Muslim, Kitab-ul-Imaan, Baab Jami' Awsaf-il-Islam, Safha 48, Hadees: 159)"}, {"id": 6887, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 22, "arabic": "عَنْ اَبِيْ عَبْدِ اللهِ جَابِرِ بْنِ عَبْدِ اللهِ الْاَنْصَارِيِّ رَضِيِ اللهُ عَنْهُمَا اَنَّ رَجُلًا سَاَلَ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: اَرَاَيْتَ اِذَا صَلَّيْتُ الْمَكْتُوْبَاتِ وَصُمْتُ رَمَضَانَ وَاَحْلَلْتُ الْحَلَالَ وَحَرَّمْتُ الْحَرَامَ وَلَمْ اَزِدْ عَلٰى ذٰلِكَ شَيْئًا اَاَدْخُلُ الْجَنَّةَ؟ قَالَ: ’’نَعَمْ.‘‘ (رَوَاہُ مُسْلِم)وَمَعْنٰی: حَرَّمْتُ الْحَرَام اِجْتَـنَبْتُہٗ. وَمَعْنٰی: اَحْلَلْتُ الْحَلَالَ فَعَلْتُہٗ مُعْتَقِدًا حِلَّہٗ.", "urdu": "حضرت سیِّدُنا ابو عبداللہ جابر بن عبداللہ انصاری رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے رسولِ اکرم صلّی اللہ علیہ واٰلہٖ وسلّم کی بارگاہ میں عرض کی: مجھے بتائیے کہ جب میں فرض نمازیں اداکروں، رمضان کے روزے رکھوں، حلال کوحلال اور حرام کو حرام جانوں اور ان کاموں پر کچھ زیادہ نہ کروں تو کیا میں جنت میں چلا جاؤں گا؟ آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ہاں۔‘‘ (مسلم، كتاب الايمان، باب الايمان الذی يدخل بہ الجنة...الخ، ص۳۷، حدیث:۱۱۰) \n حضرت سیِّدُنا امام نووی رحمۃُ اللہ علیہ فرماتے ہیں: حرام کو حرام سمجھوں کا معنیٰ یہ ہےکہ حرام سے بچوں اور حلال کو حلال جاننے کا معنیٰ یہ ہےکہ اس کے حلال ہونے کا اعتقاد رکھتے ہوئے اس پر عمل کروں۔", "roman": "Hazrat Sayyiduna Abu Abdullah Jabir Bin Abdullah Ansari RadiyAllahu Anhuma se Riwayat hai ke ek Shakhs ne Rasool-e-Akram Sallallahu Alayhi wa Sallam ki baargah mein arz ki: Mujhe bataiye ke jab main Farz namazein ada karoon, Ramazan ke roze rakhoon, Halal ko Halal aur Haram ko Haram jaanoon aur in kaamon par kuch zyada na karoon to kya main Jannat mein chala jaon ga? Aap Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Haan.''(Muslim, Kitab-ul-Imaan, Baab-ul-Imaan-illazi Yudkhalu bihil-Jannah...al-aakhir, Safha 37, Hadees: 110)\nHazrat Sayyiduna Imam Nawawi Rahmatullah Alayh farmate hain: Haram ko Haram samajhoon ka ma'na yeh hai ke Haram se bachoon aur Halal ko Halal jaanne ka ma'na yeh hai ke us ke Halal hone ka aiteqaad rakhte hue us par amal karoon."}, {"id": 6888, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 23, "arabic": "عَنْ اَبِيْ مَالِكِ الْحَارِثِ بْنِ عَاصِمِ الْاَشْعَرِيِّ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’اَلطُّهُوْرُ شَطْرُ الْاِيْمَانِ وَالْحَمْدُ لِلّٰهِ تَمْلَاُ الْمِيْزَانَ وَسُبْحٰنَ اللهِ والْحَمْدُ لِلّٰهِ تَمْلَاٰنِ اَوْ تَمْلَاُ مَا بَيْنَ السَّمٰوَاتِ والْاَرْضِ وَالصَّلَاةُ نُوْرٌ وَّالصَّدَقَةُ بُرْهَانٌ وَّالصَّبْرُ ضِيَآءٌ وَّالْقُرْاٰنُ حُجَّةٌ لَّكَ اَوْ عَلَيْكَ كُلُّ النَّاسِ يَغْدُوْ فَبَآئِعٌ نَفْسَهٗ فَمُعْتِقُهَا اَوْ مُوْبِقُهَا.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابومالک حارث بن عاصم اشعری رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ وسلّم نے ارشاد فرمایا: ’’پاکیزگی (صفائی ستھرائی) آدھا ایمان ہے اور ’’اَلْحَمْدُلِلّٰہ“ ترازو کو بھر دیتا ہے اور ’’سُبْحٰنَ اللہ“ اور ” اَلْحَمْدُلِلّٰہ“ آسمان اور زمین کے درمیان کو بھر دیتے ہیں، نماز نور ہے،صدقہ دلیل ہے، صبر روشنی ہے اور قرآن تمہارے حق میں یا تمہارے خلاف دلیل ہے۔ ہر شخص اس حال میں صبح کرتا ہے کہ وہ خود کو بیچنے والاہوتا ہے، لہٰذا وہ اپنے آپ کوآزاد کرتایا ہلاک کرتا ہے۔‘‘ ( مسلم، كتاب الطهارة، باب فضل الوضوء، ص۱۱۵، حدیث:۵۳۴)", "roman": "Hazrat Sayyiduna Abu Malik Haris Bin Aasim Ash'ari RadiyAllahu Anhu bayan karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: ''Pakeezgi (safai suthrai) aadha imaan hai aur 'Alhamdulillah' taraazu ko bhar deta hai aur 'SubhanAllah' aur 'Alhamdulillah' aasman aur Zameen ke darmiyan ko bhar dete hain, Namaz noor hai, Sadaqah daleel hai, sabr roshni hai aur Quran tumhare haq mein ya tumhare khilaf daleel hai. Har Shakhs is haal mein subah karta hai ke woh khud ko bechne wala hota hai, lihaza woh apne aap ko aazad karta ya halak karta hai.''(Muslim, Kitab-ut-Taharah, Baab Fazl-il-Wazu, Safha 115, Hadees: 534)"}, {"id": 6889, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 24, "arabic": "عَنْ اَبِيْ ذَرٍّ رَضيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيْمَا رَوٰی عَنِ اللهِ عَزَّ وَجَلَّ اَنَّهٗ قَالَ: ’’يَا عِبَادِيْ اِنِّيْ حَرَّمْتُ الظُّلْمَ عَلٰى نَفْسِيْ وَجَعَلْتُهٗ بَيْنَكُمْ مُحَرَّمًا فَلَا تَظَالَمُوْا. يَا عِبَادِيْ كُلُّكُمْ ضَالٌّ اِلَّا مَنْ هَدَيْتُهٗ فَاسْتَهْدُوْنِيْ اَهْدِكُمْ. يَا عِبَادِيْ كُلُّكُمْ جَآئِعٌ اِلَّامَنْ اَطْعَمْتُهٗ فَاسْتَطْعِمُوْنِيْ اُطْعِمْكُمْ. يَا عِبَادِيْ كُلُّكُمْ عَارٍ اِلَّا مَنْ كَسَوْتُهٗ فَاسْتَكْسُوْنِيْ اَكْسُكُمْ. يَا عِبَادِيْ اِنَّكُمْ تُخْطِئُوْنَ بِاللَّيْلِ وَالنَّهَارِ وَاَنَا اَغْفِرُ الذُّنُوْبَ جَمِيْعًا فَاسْتَغْفِرُوْنِيْ اَغْفِرْ لَكُمْ. يَا عِبَادِيْ اِنَّكُمْ لَنْ تَبْلُغُوْا ضُرِّيْ فَتَضُرُّوْنِيْ وَلَنْ تَبْلُغُوْا نَفْعِيْ فَتَنْفَعُوْنِيْ. يَا عِبَادِيْ لَوْ اَنَّ اَوَّلَكُمْ وَاٰخِرَكُمْ وَاِنْسَكُمْ وَجِنَّكُمْ كَانُوْا عَلٰى اَتْقَى قَلْبِ رَجُلٍ وَّاحِدٍ مِّنْكُمْ مَا زَادَ ذٰلِكَ فِيْ مُلْكِيْ شَيْئًا. يَا عِبَادِيْ لَوْ اَنَّ اَوَّلَكُمْ وَاٰخِرَكُمْ وَاِنْسَكُمْ وَجِنَّكُمْ كَانُوْا عَلٰى اَفْجَرِ قَلْبِ رَجُلٍ وَّاحِدٍ مِّنْكُمْ مَا نَقَصَ ذٰلِكَ مِنْ مُلْكِيْ شَيْئًا. يَا عِبَادِيْ لَوْ انَّ اَوَّلَكُمْ وَاٰخِرَكُمْ وَاِنْسَكُمْ وَجِنَّكُمْ قَامُوْا فِيْ صَعِيْدٍ وَّاحِدٍ فَسَاَلُوْنِيْ فَاَعْطَيْتُ كُلّ اِنْسَانٍ مَّسْاَلَتَهٗ مَا نَقَصَ ذٰلِكَ مِمَّا عِنْدِيْ اِلَّاكَمَا يَنْقُصُ الْمِخْيَطُ اِذَا اُدْخِلَ الْبَحْرَ. يَا عِبَادِيْ اِنَّمَا هِيَ اَعْمَالُكُمْ اُحْصِيْهَا لَكُمْ ثُمَّ اُوَفِّيْكُمْ اِيَّاهَا فَمَنْ وَّجَدَ خَيْرًا فَلْيَحْمَدِ اللهَ وَمَنْ وَّجَدَ غَيْرَ ذٰلِكَ فَلَا يَلُوْمَنَّ اِلَّا نَفْسَهٗ.‘‘(رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوذر رضی اللہ عنہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم سے ایک حدیث قدسی روایت کرتے ہیں کہ اللہ پاک نےارشاد فرمایا:\n اےمیرے بندو! میں نے ظلم کو اپنےآپ پر حرام کیا ہے اور تمہارے آپس میں بھی ظلم کو حرام فرمادیا، لہٰذاایک دوسرے پر ظلم نہ کرو۔\n اے میرے بندو! تم سب راستےسے بھٹکے ہوئے ہو، سوائے اس کے جس کو میں ہدایت دوں، لہٰذا مجھ سے ہدایت مانگو، میں تمہیں ہدایت دوں گا۔\n اےمیرے بندو! تم سب کے سب بھوکے ہو، سوائے اس کے جسے میں کھلاؤں، لہٰذا مجھ سے کھانا مانگو، میں تمہیں کھلاؤں گا۔\n اےمیرے بندو! تم سب کے سب برہنہ ہو، سوائے اس کے جس کو میں لباس پہناؤں، لہٰذا مجھ سے لباس مانگو میں تمہیں لباس دوں گا۔\n اےمیرے بندو! تم دن رات گناہ کرتے ہو اور میں ہی سب کے سب گناہ معاف کرتا ہوں، لہٰذا مجھ سےبخشش مانگو میں تمہیں بخش دوں گا۔\n اے میرے بندو! تم میرے نقصان کو نہیں پہنچ سکتے کہ مجھے نقصان پہنچادو اور نہ میرے نفع تک تمہاری رسائی ہے کہ مجھے نفع دو۔\n اےمیرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن تمہارے سب سےبڑے پرہیزگارشخص کے دل جیسے ہو جائیں تب بھی میری بادشاہت میں کچھ بڑھا نہیں سکتے۔\n اےمیرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن تم میں سے سب سے بڑے بدکار کے دل جیسے ہو جائیں تو بھی میری بادشاہت میں کچھ کمی نہیں کر سکتے۔\n اے میرے بندو! اگر تمہارے اگلے پچھلے انسان اور جن ایک میدان میں کھڑے ہوکر مجھ سے سوال کریں اور میں ہر انسان کا سوال پورا کردوں تو بھی میرے خزانوں میں کچھ کمی نہ ہوگی مگر اتنا ہی جتنا سوئی کو سمندر میں ڈال کر نکالا جائے (یعنی کچھ بھی کم نہ ہو گا)۔\n اے میرے بندو! تمہارے اعمال میرے شمار میں ہیں، میں تمہیں ان کا پورا پورا بدلہ دوں گا لہٰذا جوبھلائی پائے وہ اللہ پاک کا شکر ادا کرےاور جو اس کے علاوہ پائے تو وہ اپنے آپ ہی کو ملامت کرے۔\n( مسلم، كتاب البر والصلة والاداب، باب تحريم الظلم، ص۱۰۶۸، حدیث:۶۵۷۲)", "roman": "Hazrat Sayyiduna Abu Zar RadiyAllahu Anhu Huzoor Nabi-e-Kareem Sallallahu Alayhi wa Sallam se ek Hadees-e-Qudsi Riwayat karte hain ke Allah Paak ne irshad farmaya:\nAe Mere bando! Main ne zulm ko apne aap par Haram kiya hai aur tumhare aapas mein bhi zulm ko Haram farma diya, lihaza ek doosre par zulm na karo.\nAe Mere bando! Tum sab raaste se bhatke hue ho, siwaye us ke jis ko Main hidayat doon, lihaza Mujh se hidayat maango, Main tumhein hidayat doonga.\nAe Mere bando! Tum sab ke sab bhooke ho, siwaye us ke jise Main khilaoon, lihaza Mujh se khana maango, Main tumhein khilaoon ga.\nAe Mere bando! Tum sab ke sab barhana ho, siwaye us ke jis ko Main Libaas pehnaoon, lihaza Mujh se Libaas maango Main tumhein Libaas doonga.\nAe Mere bando! Tum din raat gunah karte ho aur Main hi sab ke sab gunah maaf karta hoon, lihaza Mujh se bakhshish maango Main tumhein bakhsh doonga.\nAe Mere bando! Tum Mere nuqsan ko nahin pohanch sakte ke Mujhe nuqsan pohancha do aur na Mere nafa tak tumhari rasaai hai ke Mujhe nafa do.\nAe Mere bando! Agar tumhare agle pichhle insaan aur jinn tumhare sab se bade parhezgaar Shakhs ke dil jaise ho jayein tab bhi Meri badshahat mein kuch barha nahin sakte.\nAe Mere bando! Agar tumhare agle pichhle insaan aur jinn tum mein se sab se bade badkaar ke dil jaise ho jayein to bhi Meri badshahat mein kuch kami nahin kar sakte.\nAe Mere bando! Agar tumhare agle pichhle insaan aur jinn ek maidan mein khade hokar Mujh se Sawaal karein aur Main har insaan ka Sawaal poora kar doon to bhi Mere khazano mein kuch kami na hogi magar itna hi jitna sui ko samandar mein daal kar nikala jaye (ya'ni kuch bhi kam na hoga).\nAe Mere bando! Tumhare a'maal Mere shumar mein hain, Main tumhein un ka poora poora badla doonga lihaza jo bhalai paaye woh Allah Paak ka shukr ada kare aur jo is ke ilawah paaye to woh apne aap hi ko malamat kare.\n(Muslim, Kitab-ul-Birr was-Silah wal-Aadab, Baab Tahreem-iz-Zulm, Safha 1068, Hadees: 6572)"}, {"id": 6890, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 25, "arabic": "عَنْ اَبِيْ ذَرٍّ رَضيَ اللهُ عَنْهُ اَيْضًا اَنَّ نَاسًا مِّنْ اَصْحَابِ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالُوْا لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَا رَسُوْلَ اللهِ! ذَهَبَ اَهْلُ الدُّثُـوْرِ بِالْاُجُوْرِ يُصَلُّوْنَ كَمَا نُصَلِّیْ وَيَصُوْمُوْنَ كَمَا نَصُوْمُ وَيَتَصَدَّقُوْنَ بفُضُوْلِ اَمْوَالِهِمْ. قَالَ: ’’ اَوَ لَيْسَ قَدْ جَعَلَ اللهُ لَكُمْ مَا تَصَّدَّقُوْنَ؟ اِنَّ بِكُلِّ تَسْبِيْحَةٍ صَدَقَةً وَّكُلِّ تَكْبِيْرَةٍ صَدَقَةً وَّكُلِّ تَحْمِيْدَةٍ صَدَقَةً وَّكُلِّ تَهْلِيْلَةٍ صَدَقَةً وَّاَمْرٌ بِالْمَعْرُوْفِ صَدَقَةٌ وَّنَهْيٌ عَنْ مُّنْكَرٍ صَدَقَةٌ وَّفِيْ بُضْعِ اَحَدِكُمْ صَدَقَةٌ.‘‘ قَالُوا: يَا رَسُوْلَ اللهِ! اَ يَاْتِيْ اَحَدُنَا شَهْوَتَهٗ وَيَكُوْنُ لَهٗ فِيْهَا اَجْرٌ؟ قَالَ: ’’ اَرَاَيْتُمْ لَوْ وَضَعَهَا فِيْ حَرَامٍ اَكَانَ عَلَيْهِ وِزْرٌ؟ فَكَذٰلِكَ اِذَا وَضَعَهَا فِي الْحَلالِ كَانَ لَهٗ اَجْرٌ.‘‘ (رَوَاہُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوذر غفاری رضی اللہ عنہ سے ہی روایت ہے کہ بعض صحابَۂ کرام علیہمُ الرّضوان نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مال دار لوگ اجر و ثواب میں بڑھ گئے، وہ ہماری طرح نماز پڑھتے ہیں، ہماری طرح روزے رکھتے ہیں اور اپنے زائد مال سے صدقہ دیتے ہیں (جبکہ ہمارے پاس ضرورت سے زائد مال نہیں ہے جس سے ہم صدقہ کریں)۔ اللہ پاک کے آخری نبی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’کیا اللہ پاک نے تمہارے لئے وہ اعمال نہیں بنائے جن کے ذریعے تم صدقہ کرو؟ بے شک ہر تسبیح (سُبْحٰنَ اللہ کہنا) صدقہ ہے، ہر تکبیر (اللہ اَکْبَر کہنا) صدقہ ہے، ہر تحمید (اَلْحَمْدُلِلّٰہ کہنا) صدقہ ہے، ہر تہلیل (لَااِلٰہَ اِلَّااللہ کہنا) صدقہ ہے، نیکی کا حکم دینا صدقہ ہے، بُرائی سے منع کرنا صدقہ ہے اور تمہاری شرم گاہ میں بھی صدقہ ہے۔‘‘ صحابَۂ کرام علیہمُ الرّضوان نے عرض کی: یارسول اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! ہم میں سے کوئی شخص اپنی خواہش پوری کرے تو کیا اس میں بھی اس کے لئے اجر ہے؟ ارشاد فرمایا: ’’مجھے بتاؤ کہ اگر وہ حرام جگہ اپنی خواہش پوری کرتا تو اس پر گناہ نہ ملتا؟ اسی طرح جب وہ حلال جگہ خواہش پوری کرے گا تو اس کے لئے ثواب ہوگا۔‘‘( مسلم، كتاب الزكاة، باب بيان ان اسم الصدقة يقع على كل نوع من المعروف، ص۳۹۰، حدیث:۲۳۲۹)", "roman": "Hazrat Sayyiduna Abu Zar Ghifari Radiyallahu Anhu se hi riwayat hai ke ba'az Sahaba-e-Kiram Alaihimur Ridwan ne bargah-e-Risalat mein arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Maal daar log ajr-o-sawab mein barh gaye, woh hamari tarah Namaz parhte hain, hamari tarah Roza rakhte hain aur apne zaid Maal se Sadaqah dete hain (jabke hamare paas zaroorat se zaid Maal nahi hai jis se hum Sadaqah karein). Allah Paak ke aakhri Nabi Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Kya Allah Paak ne tumhare liye woh a'maal nahi banaye jin ke zariye tum Sadaqah karo? Beshak har Tasbeeh (SubhanAllah kehna) Sadaqah hai, har Takbeer (Allah Akbar kehna) Sadaqah hai, har Tahmeed (Alhamdulillah kehna) Sadaqah hai, har Tahleel (La ilaha illallah kehna) Sadaqah hai, neki ka Hukm dena Sadaqah hai, burai se mana karna Sadaqah hai aur tumhari Sharm-gah mein bhi Sadaqah hai.' Sahaba-e-Kiram Alaihimur Ridwan ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Hum mein se koi Shakhs apni khwahish poori kare to kya is mein bhi us ke liye ajr hai? Irshad farmaya: 'Mujhe batao ke agar woh Haram jagah apni khwahish poori karta to is par gunah na milta? Isi tarah jab woh Halal jagah khwahish poori karega to is ke liye sawab hoga.' (Muslim, Kitaab-uz-Zakat, Baab bayan an ism-us-Sadaqah yaqa'u ala kulli nau'in min-al-Ma'Roof, safa 390, Hadees: 2329)"}, {"id": 6891, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 26, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’كُلُّ سَلَامٰى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيْهِ الشَّمْسُ یَعْدِلُ بَيْنَ اثْنَيْنِ صَدَقَةٌ وَّیُعِيْنُ الرَّجُلَ فِيْ دَابَّتِهٖ فَیَحْمِلُهٗ عَلَيْهَا اَوْ یَرْفَعُ لَهٗ عَلَيْهَا مَتَاعَهٗ صَدَقَةٌ وَّالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ وَّبِكُلِّ خُطْوَةٍ یَّمْشِيْهَا اِلَى الصَّلَاةِ صَدَقَةٌ وَّیُمِيْطُ الْاَذٰى عَنِ الطَّرِيْقِ صَدَقَةٌ.‘‘(رَوَاهُ الْبُخَارِیُّ وَمُسْلِمٌ)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسُوْلُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’ہر وہ دن جس میں سورج طلوع ہو(یعنی روزانہ) انسان کے ہر جوڑ پر صدقہ ہے،دو آدمیوں کے درمیان انصاف کرنا صدقہ ہے، آدمی کو اس کی سواری پر سوار کرانے یا اس کا سامان رکھوانے پر مدد کرنا صدقہ ہے، اچھی گفتگو صدقہ ہے، نماز کی طرف اٹھنےوالا ہر قدم صدقہ ہے اور راستے سے تکلیف دہ چیز دور کرنا صدقہ ہے۔‘‘ \n (مسلم، كتاب الزکاة، باب بیان ان اسم الصدقة یقع...الخ، ص۳۹۱، حدیث:۲۳۳۵۔ بخاری، کتاب الجھاد، باب فضل من حمل متاع صاحبہ فی السفر، ۲/ ۲۷۹، حدیث:۲۸۹۱، بتغیر قلیل)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu se riwayat hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Har woh din jis mein sooraj tulu ho (yani rozana) insaan ke har jor par Sadaqah hai, do aadmiyon ke darmiyan insaaf karna Sadaqah hai, aadmi ko us ki sawari par sawar karane ya us ka Maal rakhwane par madad karna Sadaqah hai, achi guftagu Sadaqah hai, Namaz ki taraf uthne wala har qadam Sadaqah hai aur raaste se takleef deh cheez door karna Sadaqah hai.' (Muslim, Kitaab-uz-Zakat, Baab bayan an ism-us-Sadaqah yaqa'u... al-kh, safa 391, Hadees: 2335. Bukhari, Kitaab-ul-Jihad, Baab fazl man hamala mata'a sahibihi fis-safar, 2/279, Hadees: 2891, bataghayyur-e-qaleel)"}, {"id": 6892, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 27, "arabic": "عَنِ النَّوَّاسِ بْنِ سَمْعَانَ رَضيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيهِ وَسَلَّمَ قَالَ: ’’اَلْبِرُّ حُسْنُ الْخُلُقِ وَالْاِثْمُ مَا حَاكَ فِيْ نَفْسِكَ وَكَرِهْتَ اَنْ يَّطَّلِعَ عَلَيْهِ النَّاسُ.‘‘ (رَوَاهُ مُسْلِم)\nوَعَنْ وَابِصَةَ بْنِ مَعْبَدٍرَضِىَ اللهُ عَنْهُ قَالَ: اَتَيْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ’’جِئْتَ تَسْاَلُ عَنِ الْبِرِّ؟‘‘ قُلْتُ: نَعَمْ. قَالَ: ’’اِسْتَفْتِ قَلْبَكَ، اَلْبِرُّ مَا اطْمَاَنَّتْ اِلَيْهِ النَّفْسُ وَاطْمَاَنَّ اِلَيْهِ الْقَلْبُ وَالْاِثْمُ مَا حَاكَ فِيْ النَّفْسِ وَتَرَدَّدَ فِيْ الصَّدْرِ وَاِنْ اَفْتَاكَ النَّاسُ وَافْتَوْكَ.‘‘ (حَدِيْثٌ حَسَنٌ، رَوَيْنَاهٗ فِیْ مُسْنَدَیَ الْاِمَامَيْنِ اَحْمَدَ ابْنِ حَنْبَلٍ وَّالدَّارَمِیِّ رَحِمَھُمَا اللّٰہ تعالٰی بِاِسْنَادٍ حَسَنٍ)", "urdu": "حضرت سیِّدُنا نواس بن سمعان رضی اللہ عنہ سے مروی ہے کہ حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’نیکی حسن اخلاق کا نام ہے اور گناہ وہ ہے جو تیرے دل میں کھٹکے اور تجھے اس پر لوگوں کا مطلع ہونا (اِطلاع پانا) ناپسند ہو۔‘‘ \n( مسلم، كتاب البر والصلة والاداب، باب تفسير البر والاثم، ص۱۰۶۱، حدیث:۶۵۱۷)\n حضرت سیِّدُنا وابصہ بن معبد رضی اللہ عنہ بیان کر تے ہیں کہ میں بارگاہِ رسالت میں حاضر ہوا تو آپ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا:’’تم نیکی کے بارے میں پوچھنے آئے ہو؟ میں نے عرض کی: جی ہاں۔ ارشاد فرمایا: اپنے دل سے پوچھو، نیکی وہ ہے جس پر تمہارا نفس مطمئن ہو اور اطمینان قلبی حاصل ہو اور گناہ وہ ہے جو تمہارے نفس میں کھٹکے اور دل میں شک پیدا کرے ، اگرچہ لوگ تمہیں کچھ بھی فتویٰ دیں، اگرچہ لوگ تمہیں فتویٰ دیں ۔‘‘ (مسند احمد، مسند الشامیین، حدیث وابصة بن معبد اسدی، ۶/ ۲۹۲، حدیث:۱۸۹۲۳، بتغیر قلیل۔ دارمی، کتاب البیوع، باب دع مایریبک الی ما لا یریبک، ۲/ ۳۲۰، حدیث:۲۵۳۳)\n (یہ حدیث حسن ہے۔ اسے حضرت سیِّدُنا امام حمد بن محمد بن حنبل اور حضرت سیِّدُنا حافظ ابو محمد عبد اللہ بن عبدالرحمٰن بن فضل بن بہرام دارمی رحمۃ اللہ علیہما نے اپنی اپنی مسند (مسند احمد اور سنن دارمی) میں حسن سند کے ساتھ روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Nawwas bin Sam'an Radiyallahu Anhu se Marwi hai ke Huzoor Nabi-e-Kareem Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Neki Hasan akhlaq ka naam hai aur gunah woh hai jo tere dil mein khatke aur tujhe is par logon ka muttali' hona (ittila' paana) na-pasand ho.' (Muslim, Kitaab-ul-Birri was-Silati wal-Adab, Baab tafseer-ul-birri wal-ism, safa 1061, Hadees: 6517). Hazrat Sayyiduna Wabsa bin Ma'bad Radiyallahu Anhu bayan karte hain ke main bargah-e-Risalat mein hazir hua to Aap Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Tum neki ke baare mein poochne aaye ho?' Main ne arz ki: Ji haan. Irshad farmaya: 'Apne dil se poocho, neki woh hai jis par tumhara nafs mutma'in ho aur itminan-e-qalbi hasil ho aur gunah woh hai jo tumhare nafs mein khatke aur dil mein shak paida kare, agarche log tumhein kuch bhi Fatwa dein, agarche log tumhein Fatwa dein.' (Musnad-e-Ahmed, Musnad-ush-Shaamiyeen, Hadees Wabsa bin Ma'bad Asadi, 6/292, Hadees: 18923, bataghayyur-e-qaleel. Sunan Darimi, Kitaab-ul-Buyu', Baab da' ma yaribuka ila ma la yaribuka, 2/320, Hadees: 2533). (Yeh Hadees Hasan hai. Ise Hazrat Sayyiduna Imam Muhammad bin Muhammad bin Hanbal aur Hazrat Sayyiduna Hafiz Abu Muhammad Abdullah bin Abdur-Rahman bin Fazl bin Bahram Darimi Rahmatullah Alayhima ne apni apni Musnad (Musnad-e-Ahmed aur Sunan Darimi) mein Hasan Sanad ke saath riwayat kiya hai.)"}, {"id": 6893, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 28, "arabic": "عَنْ اَبِيْ نَجِيْحِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضيَ اللهُ عَنْهُ قَالَ: وَعَظَنَا رَسُوْلُ اللهِ صلّی اللهِ علیہ وسلّم مَوْعِظَةً وَّجِلَتْ مِنهَا الْقُلُوْبُ وَذَرَفَتْ مِنهَا الْعُيُوْنُ. فَقُلْنَا: يَا رَسُوْلَ اللهِ صلّی اللهِ علیہ وسلّم ! كَاَنَّهَا مَوْعِظَةُ مُوَدِّعٍ فَاَوْصِنَا. قَالَ: ’’اُوْصِيْكُمْ بِتَقْوَى اللهِ وَالسَّمعِ وَالطَّاعَةِ وَاِنْ تَاَمَّرَ عَلَيْكُمْ عَبْدٌ، فَاِنَّهٗ مَنْ يَّـعِشْ مِنْكُمْ فَسَيَرٰى اِخْتِلَافًا كَثِيْرًا، فَعَلَيْكُمْ بِسُنَّتِيْ وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِيْنَ الْمَهْدِيِّـيْنَ عَضُّوْا عَلَيْهَا بِالنَّوَاجِذِ وَاِيَّاكُمْ وَمُحْدَثَاتِ الْاُمُوْرِ فَاِنَّ كُلَّ بِدْعَةٍ ضَلَالَةٌ.‘‘ \n(رَوَاهُ اَبُوْ دَاؤُدَ وَالتِّرْمَذِیُّ وَقَالَ: حَدِيْثٌ حَسَنٌ صَحِيْحٌ)", "urdu": "ترجمہ:حضرت سیِّدُنا ابونجیح عِرباض بن ساریہ رضی اللہ عنہ فرماتے ہیں کہ حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم نے ہمیں ایک ایسی نصیحت فرمائی جس سے دل دہل گئے اور آنسو بہنے لگے۔ ہم نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! ایسا لگ رہا ہے کہ یہ الوداعی نصیحت ہے، لہٰذا ہمیں کچھ وصیت فرمادیں۔ ارشاد فرمایا: ’’میں تمہیں اللہ پاک سے ڈرنے، حاکم کی بات سننے اور فرماں برداری کرنے کی نصیحت کرتا ہوں اگرچہ کوئی غلام ہی تم پر حاکم ہو کیونکہ تم میں سے جو زندہ رہے گا عنقریب وہ بہت اختلافات دیکھے گا۔ لہٰذا تم پر میری سنت اور ہدایت یافتہ خلفائے راشدین کا طریقہ اختیار کرنا لازم ہے، اسے مضبوطی سے تھام لو اور نئے کاموں سے بچو کہ ہربدعت گمراہی ہے۔‘‘(ترمذی، کتاب العلم، باب ماجاء فی الاخذ فی السنة...الخ، ۴/ ۳۰۸، حدیث:۲۶۸۵، بتغیر قلیل ۔ ابوداود، كتاب السنة، باب فی لزوم السنة، ۴/ ۲۶۷، حدیث:۴۶۰۷)\n(اس حدیث کو حضرت سیِّدُنا امام ابو داود سلیمان بن اشعث ازدی سجستانی اور حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہما نے (سنن ابو داود اور جامع ترمذی میں) روایت کیا ہے اور حضرت سیِّدُنا امام ترمذی رحمۃ اللہ علیہ نے فرمایا: یہ حدیث حسن صحیح ہے۔)", "roman": "Tarjuma: Hazrat Sayyiduna Abu Najeeh Irbaaz bin Sariyah Radiyallahu Anhu farmate hain ke Huzoor Nabi-e-Paak Sallallahu Alaihi wa Sallam ne hamein ek aisi naseehat farmayi jis se dil dehal gaye aur aansoo behne lage. Hum ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Aisa lag raha hai ke yeh alwida'i naseehat hai, lihaza hamein kuch Wasiyat farmadein. Irshad farmaya: 'Main tumhein Allah Paak se darne, Imam ki baat sunne aur farmanbardari karne ki naseehat karta hoon agarche koi ghulam hi tum par Imam ho kyunke tum mein se jo zinda rahega anqareeb woh bohat ikhtilafat dekhega. Lihaza tum par meri Sunnat aur hidayat yafta Khulafa-e-Rashideen ka Tareeqa ikhtiyar karna laazim hai, ise mazbooti se thaam lo aur naye kaamon se bacho ke har Bid'at Gumraah hai.' (Tirmizi, Kitaab-ul-Ilm, Baab ma ja'a fil-akhzi fis-Sunnati... al-kh, 4/308, Hadees: 2685, bataghayyur-e-qaleel. Abu Dawood, Kitaab-us-Sunnah, Baab fi luzoom-is-Sunnah, 4/267, Hadees: 4607). (Is Hadees ko Hazrat Sayyiduna Imam Abu Dawood Sulaiman bin Ash'as Azdi Sajistani aur Hazrat Sayyiduna Imam Abu Isa Muhammad bin Isa Tirmizi Rahmatullah Alayhima ne (Sunan Abu Dawood aur Jami' Tirmizi mein) riwayat kiya hai aur Hazrat Sayyiduna Imam Tirmizi Rahmatullah Alayh ne farmaya: Yeh Hadees Hasan Saheeh hai.)"}, {"id": 6894, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 29, "arabic": "عَنْ مُعَاذِ بْنِ جَبَلٍ رَضيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم ! اَخْبِرْنِيْ بِعَمَلٍ يُّدْخِلُنِيَ الْجَنَّةَ وَيُبَاعِدُنِيْ مِنَ النَّارِ. قَالَ: ’’لَقَدْ سَاَلْتَ عَنْ عَظِيْـمٍ وَّاِنَّهٗ لَيَسِيْرٌ عَلٰى مَنْ يَسَّرَهُ اللهُ تَعَالٰى عَلَيْهِ؛ تَعْبُدُ اللهَ لَا تُشْرِكُ بِهٖ شَيْئًا وَّتُقِيْمُ الصَّلَاةَ وَتُؤْتِيَ الزَّكَاةَ وَتَصُوْمُ رَمَضَانَ وَتَحُجُّ الْبَـيْتَ.‘‘ ثُمَّ قَالَ: ’’اَلَااَدُلُّكَ عَلٰى اَبْوَابِ الْخَيْرِ؛ اَلصَّوْمُ جُنَّةٌ وَّالصَّدَقَةُ تُطْفِئُ الْخَطِيْئَةَ كَمَا يُطْفِئُ الْمَآءُ النَّارَ وَصَلَاةُ الرَّجُلِ مِنْ جَوْفِ اللَّيْلِ.‘‘ ثُمَّ تَلَا: ’’ تَتَجَافٰى جُنُوْبُهُمْ عَنِ الْمَضَاجِعِ ‘‘ حَتّٰی بَلَغَ ’’ یَعْمَلُوْنَ ‘‘. ثُمَّ قَالَ: ’’اَلَا اُخْبِرُكَ بِرَاْسِ الْاَمْرِ وَعَمُوْدِهٖ وَذِرْوَةِ سَنَامِهٖ؟‘‘ قُلْتُ: بَلٰى يَا رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم ! قَالَ: ’’رَاْسُ الْاَمْرِ اَلْاِسْلَامُ وَعَمُوْدُهٗ اَلصَّلَاةُ وَذِرْوَةُ سَنَامِهٖ اَلْجِهَادُ.‘‘ ثُمَّ قَالَ: ’’اَلَا اُخْبِرُكَ بِمِلَاكِ ذٰلِكَ كُلِّهٖ؟‘‘ قُلْتُ:بَلٰى يَا رَسُوْلَ اللهِ صلّی اللہ علیہ وسلّم !. فَاَخَذَ بِلِسَانِهٖ. ثُمَّ قَالَ: ’’ كُفَّ عَلَيْكَ هٰذَا.‘‘ قُلْتُ :يَا نَبِيَّ اللهِ! وَاِنَّا لَمُؤَاخَذُوْنَ بِمَا نَتَكَلَّمُ بِهٖ؟ فَقَالَ: ’’ثَكِلَتْكَ اُمُّكَ؛ وَهَلْ يَكُبُّ النَّاسَ فِيْ النَّارِ عَلٰى وُجُوهِهِمْ. اَوْ قَالَ: عَلٰى مَنَاخِرِهِمْ اِلَّا حَصَائِدُ اَلْسِنَتِهِمْ.‘‘\n(رَوَاهُ التِّرْمِذِیُّ وَقَالَ: حَدِيْثٌ حَسَنٌ صَحِيْحٌ)", "urdu": "حضرت سیِّدُنا معاذ بن جبل رضی اللہ عنہ بیان کرتے ہیں کہ میں نے بارگاہِ رسالت میں عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے ایسے عمل کے بارے میں بتائیے جو مجھے جنت میں داخل کردے اور آگ (جہنم) سے دور کردے۔ اللہ پاک کے آخری نبی صلّی اللہ علیہ والہ وسلّم نے ارشاد فرمایا:’’تم نے بہت بڑی بات کے بارے میں پوچھا ہے بےشک وہ اسی پر آسان ہے جس کے لئے اللہ پاک آسان فرمادے۔ (وہ یہ ہے)تم اللہ پاک کی عبادت اس طرح کرو کہ کسی کو بھی اس کا شریک نہ ٹھہراؤ ، نماز قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو اور بَیْتُ اللہ کا حج کرو۔‘‘ پھر ارشاد فرمایا: ’’کیا میں بھلائی کے دروازوں کی طرف تمہاری راہ نمائی نہ کروں؟ روزہ ڈھال ہے اور صدقہ خطاؤں کو ایسے مٹادیتا ہے جیسے پانی آگ کو بجھا دیتا ہے اور بندے کا رات کے درمیانی حصہ میں نماز پڑھنا۔‘‘ پھر آپ صلّی اللہ علیہ والہ وسلّم نے یہ آیات مبارکہ تلاوت فرمائیں:\nتَتَجَافٰى جُنُوْبُهُمْ عَنِ الْمَضَاجِعِ یَدْعُوْنَ رَبَّهُمْ خَوْفًا وَّ طَمَعًا٘-وَّ مِمَّا رَزَقْنٰهُمْ یُنْفِقُوْنَ(۱۶) فَلَا تَعْلَمُ نَفْسٌ مَّاۤ اُخْفِیَ لَهُمْ مِّنْ قُرَّةِ اَعْیُنٍۚ-جَزَآءًۢ بِمَا كَانُوْا یَعْمَلُوْنَ(۱۷) (پ ۲۱، السجدة:۱۶، ۱۷)\nترجمہ کنزالایمان: ان کی کروٹیں جدا ہوتی ہیں خواب گاہوں سے اور اپنے رب کو پکارتے ہیں ڈرتے اور امید کرتے اور ہمارے دیئے ہوئے میں سے کچھ خیرات کرتے ہیں تو کسی جی کو نہیں معلوم جو آنکھ کی ٹھنڈک ان کے لئے چھپا رکھی ہے صلہ اُن کے کاموں کا۔\n پھر ارشاد فرمایا: ’’کیا میں تمہیں معاملے (یعنی دین)کی اصل، اس کے ستون اور اس کی بلندی کے بارے میں نہ بتاؤں؟‘‘ میں نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیوں نہیں (ضرور بتائیے)۔ ارشادفرمایا: ’’معاملے کی اصل اسلام، اس کا ستون نماز اور اس کی بلندی جہاد ہے۔‘‘ پھر ارشاد فرمایا: ’’کیا میں تمہیں ان سب کی اصل کے بارے میں نہ بتاؤں؟‘‘ میں نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیوں نہیں۔ آپ نے اپنی زبان مبارک پکڑ کر ارشاد فرمایا: ’’اسے قابو میں رکھو۔‘‘ میں نے عرض کی: یارسولَ اللہ صلّی اللہ علیہ والہ وسلّم! کیا گفتگو پر بھی ہماری پکڑ ہوگی؟ ارشاد فرمایا: ’’اے معاذ! تیری ماں تجھے روئے! لوگوں کو ان کے منہ کے بل یا فرمایا ان کے نتھنوں کے بل ان کی زبانوں کی کھیتی ہی جہنم میں گرائے گی۔‘‘ (ترمذی، كتاب الايمان عن رسول الله ، باب ما جاء فی حرمة الصلاة، ۴/۲۸۰، حدیث: ۲۶۲۵)\n (اس حدیث کو حضرت سیِّدُنا امام محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہنے (جامع ترمذی میں) روایت کیا اور فرمایا: یہ حدیث حسن صحیح ہے۔)", "roman": "Hazrat Sayyiduna Mu'az bin Jabal Radiyallahu Anhu bayan karte hain ke main ne bargah-e-Risalat mein arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Mujhe aise a'mal ke baare mein bataiye jo mujhe Jannat mein dakhil karde aur aag (Jahannam) se door karde. Allah Paak ke aakhri Nabi Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Tum ne bohat bari baat ke baare mein poocha hai beshak woh isi par aasaan hai jis ke liye Allah Paak aasaan farmade. (Woh yeh hai) tum Allah Paak ki ibadat is tarah karo ke kisi ko bhi is ka shareek na thahrao, Namaz qaim karo, Zakat ada karo, Ramazan ke Roza rakho aur Baitullah ka Hajj karo.' Phir irshad farmaya: 'Kya main bhalai ke darwazon ki taraf tumhari rahnumai na karoon? Roza dhaal hai aur Sadaqah khataon ko aise mita deta hai jaise paani aag ko bujha deta hai aur bande ka raat ke darmiyani hissa mein Namaz parhna.' Phir Aap Sallallahu Alaihi wa Sallam ne yeh aayat-e-mubaraka tilawat farmayin: 'Tatajafa junubuhum anil-madaji'i yad'oona Rabbahum khaufan wa tama'an wa mimma razaqnahum yunfiqun. Fala ta'lamu nafsun ma ukhfiya lahum min qurrati a'yunin jaza'an bima kanu ya'malun.' (P 21, As-Sajdah: 16, 17). Tarjuma Kanz-ul-Iman: Un ki karwatein juda hoti hain khwab-gahon se aur apne Rabb ko pukarte hain darte aur umeed karte aur hamare diye hue mein se kuch khairat karte hain to kisi jee ko nahi maloom jo aankh ki thandak un ke liye chupa rakhi hai sila un ke kaamon ka. Phir irshad farmaya: 'Kya main tumhein mu'amle (yani Deen) ki asal, is ke sutoon aur is ki bulandi ke baare mein na bataoon?' Main ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Kyun nahi (zaroor bataiye). Irshad farmaya: 'Mu'amle ki asal Islam, is ka sutoon Namaz aur is ki bulandi Jihad hai.' Phir irshad farmaya: 'Kya main tumhein in sab ki asal ke baare mein na bataoon?' Main ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Kyun nahi. Aap ne apni zaban-e-mubarak pakar kar irshad farmaya: 'Ise qaboo mein rakho.' Main ne arz ki: Ya Rasoolullah Sallallahu Alaihi wa Sallam! Kya guftagu par bhi hamari pakar hogi? Irshad farmaya: 'Ae Mu'az! Teri maa tujhe roye! Logon ko un ke munh ke bal ya farmaya un ke nathnon ke bal un ki zabanon ki kheti hi Jahannam mein giraye gi.' (Tirmizi, Kitaab-ul-Iman an Rasoolillah, Baab ma ja'a fi hurmati-s-Salah, 4/280, Hadees: 2625). (Is Hadees ko Hazrat Sayyiduna Imam Muhammad bin Isa Tirmizi Rahmatullah Alayh ne (Jami' Tirmizi mein) riwayat kiya aur farmaya: Yeh Hadees Hasan Saheeh hai.)"}, {"id": 6895, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 30, "arabic": "عَنْ اَبِيْ ثَعْلَبَةَ الْخُشَنِيِّ جُرْثُوْمِ بْنِ نَاشِرٍ رَضيَ اللهُ عَنْهُ عَنْ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’اِنَّ اللهَ فَرَضَ فَرَائِضَ فَلَا تُضَيِّعُوْهَا وَحَدَّ حُدُوْدًا فَلَا تَعْتَدُوْهَا وَحَرَّمَ اَشْيَآءَ فَلا تَنْتَهِكُوْهَا وَسَكَتَ عَنْ اَشْيَاءَ رَحْمَةً لَّكُمْ غَيْرَ نِسْيَانٍ فَلَا تَبْحَثُوْا عَنْهَا.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ الدَّارَقُطْنِیُّ وَغَيْرُہٗ)", "urdu": "حضرت سیِّدُنا ابوثعلبہ خشنی جُرثوم بن ناشر رضی اللہ عنہ سے مروی ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’بےشک اللہ پاک نےکچھ چیزیں فرض فرمائی ہیں انہیں ضائع نہ کرو، کچھ حدود مقرر کی ہیں ان سے آگے نہ بڑھو، بعض چیزوں کو حرام کیا ہے ان کی حرمت کو پامال نہ کرو اور کچھ چیزوں کے بارے میں بغیر بھولے محض تم پر رحمت کرتے ہوئےخاموشی برتی ہے، لہٰذا ان کے بارے میں بحث نہ کرو۔‘‘ (دارقطنی، كتاب الرضاع، ۴/ ۲۱۷، حدیث:۴۳۵۰)\n(یہ حدیث حسن صحیح ہے اسے حضرت سیِّدُنا امام علی بن عمر دار قطنی رحمۃ اللہ علیہاور دیگر محدثین نے روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abu Sa'laba Khushni Jurthum bin Nashir Radiyallahu Anhu se Marwi hai ke Rasoolullah Sallallahu Alaihi wa Sallam ne irshad farmaya: 'Beshak Allah Paak ne kuch cheezein Farz farmayi hain unhein zaya na karo, kuch hudood muqarrar ki hain un se aage na barho, ba'az cheezon ko Haram kiya hai un ki hurmat ko paamal na karo aur kuch cheezon ke baare mein baghair bhoole mahaz tum par Rahmat karte hue khamoshi barti hai, lihaza un ke baare mein behas na karo.' (Daraqutni, Kitaab-ur-Riza', 4/217, Hadees: 4350). (Yeh Hadees Hasan Saheeh hai ise Hazrat Sayyiduna Imam Ali bin Umar Daraqutni Rahmatullah Alayh aur deegar Muhaddiseen ne riwayat kiya hai.)"}, {"id": 6896, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 31, "arabic": "عَنْ اَبِی الْعَبَّاسِ سَهْلِ بْنِ سَعْدِ السَّاعِدِیِّ رَضِیَ اللهُ عَنْهُ قَالَ: جَآءَ رَجُلٌ اِلَى النَّبِیِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُوْلَ اللهِ! دُلَّنِیْ عَلٰى عَمَلٍ اِذَا عَمَلْتُهٗ اَحَبَّنِیَ اللهُ وَاَحَبَّنِیَ النَّاسُ؟ فَقَالَ: ’’اِزْهَدْ فِي الدُّنْيَا يُحِبُّكَ اللهُ وَازْهَدْ فِيْمَا عِنْدَ النَّاسِ يُحِبُّكَ النَّاسُ.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ ابْنُ مَاجَة وَغَيْرُهٗ بِاَسَانِيْدَ حَسَنَةً)", "urdu": "حضرت سیِّدُنا ابوالعباس سہل بن سعد ساعِدی رضی اللہ عنہ بیان کرتے ہیں کہ ایک شخص نے بارگاہِ رسالت میں حاضر ہو کر عرض کی: یارسولَ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم ! مجھے ایسا عمل بتائیے کہ جب میں اسے کروں تو اللہ پاک مجھ سے محبت فرمائے اور لوگ بھی مجھ سے محبت کرنے لگیں۔ ارشاد فرمایا: ’’دنیا سے بےرغبت ہوجاؤاللہ پاک تم سے محبت فرمائے گا اور لوگوں کے پاس جو کچھ ہےاس سے کنارہ کشی اختیار کر لو تو لوگ بھی تم سے محبت کریں گے۔‘‘ \n(ابن ماجہ، كتاب الزهد، باب الزهد فی الدنيا، ۴/ ۴۲۲، حدیث:۴۱۰۲)\n (یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو عبد اللہ محمد بن یزید بن ماجہ رحمۃ اللہ علیہاور دیگر محدثین نے حسن سندوں کے ساتھ روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abul Abbas Sahl bin Sa'ad Sa'idi Radiyallahu Anhu bayan karte hain ke ek Shakhs ne bargah-e-Risalat mein hazir ho kar arz ki: Ya Rasoolullah Sallallahu Alayhi wa Sallam! Mujhe aisa amal bataiye ke jab main ise karoon to Allah Paak mujh se Mohabbat farmaye aur log bhi mujh se Mohabbat karne lagen. Irshad farmaya: 'Duniya se beraghabat ho jao Allah Paak tum se Mohabbat farmaye ga aur logon ke paas jo kuch hai us se kinara kashi ikhtiyar kar lo to log bhi tum se Mohabbat karenge.' (Ibn-e-Majah, Kitaab-uz-Zuhd, Baab-uz-Zuhd fid-Dunya, 4/422, Hadees: 4102) (Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Abdullah Muhammad bin Yazeed bin Majah Rahmatullah Alayh aur deegar Muhaddiseen ne Hasan Sanadon ke sath Riwayat kiya hai.)"}, {"id": 6897, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 32, "arabic": "عَنْ اَبِيْ سَعِيْدٍ سَعْدِ بْنِ مَالِكِ بْنِ سِنَانِ الْخُدَرِيِّ رَضيَ اللهُ عَنْهُ اَنَّ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’لَاضَرَرَ وَلَا ضِرَارَ.‘‘\n(حَدِيْثٌ حَسَنٌ رَوَاهُ ابْنُ مَاجَه، وَالدَّارُقُطْنِیُّ وَغَيْرُهُمَا مُسْنَدًا وَرَوَاهُ مَالِكٌ رَحِمَہُمُ اللّٰہ تعالٰی فِی الْمُوَطَّا عَنْ عَمْرِو بْنِ يَحْيٰى عَنْ اَبِيْهٖ عَنِ النَّبِیِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُرْسَلًا فَاَسْقَطَ اَبَا سَعِيْدٍ وَّلَهٗ طُرُقٌ يُّقَوِّیْ بَعْضُهَا بَعْضًا)", "urdu": "حضرت سیِّدُنا ابوسعید سعد بن مالک بن سنان خدری رضی اللہ عنہ سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’نہ خود نقصان اٹھاؤ اور نہ ہی (دوسروں کو) نقصان پہنچاؤ۔‘‘ \n(ابن ماجہ، كتاب الاحكام، باب من بنى فی حقہ ما يضر بجاره، ۳/ ۱۰۶، حدیث:۲۳۴۰ ۔ دار قطنی، کتاب الاقضیة والاحکام، ۴/ ۲۶۹، حدیث:۴۴۹۵)\n(یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو عبد اللہ محمد بن یزید بن ماجہ اور حضرت سیِّدُنا امام علی بن عمر دار قطنی رحمۃ اللہ علیہما اور دیگر محدثین نے سند کے ساتھ روایت کیا ہے۔ جبکہ حضرت سیِّدُنا امام مالک رحمۃ اللہ علیہ نے موطا میں حضرت سیِّدُنا عمرو بن یحییٰ سے، انہوں نے اپنے والد حضرت سیِّدُنا یحییٰ رحمۃ اللہ علیہما کی سند سے حضور نبی پاک صلّی اللہ علیہ والہ وسلّم سے (آخری روای کو ذکر کئے بغیر) مرسلاً روایت کیا ہے کہ حضرت سیِّدُنا ابو سعید رضی اللہ عنہ کو ذکر نہیں کیا۔ اس روایت کی اور بھی سندیں ہیں جو ایک دوسرے کو تقویت دیتی ہیں۔)", "roman": "Hazrat Sayyiduna Abu Saeed Sa'ad bin Maalik bin Sinaan Khudri Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: 'Na khud nuqsan uthao aur na hi (dusron ko) nuqsan pahunchao.' (Ibn-e-Majah, Kitaab-ul-Ahkaam, Baab man bana fi haqqihi ma yadurru bi-jarihi, 3/106, Hadees: 2340. Darqutni, Kitaab-ul-Aqziya wal-Ahkaam, 4/269, Hadees: 4495) (Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Abdullah Muhammad bin Yazeed bin Majah aur Hazrat Sayyiduna Imam Ali bin Umar Darqutni Rahmatullah Alayhima aur deegar Muhaddiseen ne Sanad ke sath Riwayat kiya hai. Jabke Hazrat Sayyiduna Imam Malik Rahmatullah Alayh ne Mu'atta mein Hazrat Sayyiduna Amr bin Yahya se, unhon ne apne walid Hazrat Sayyiduna Yahya Rahmatullah Alayhima ki Sanad se Huzoor Nabi Paak Sallallahu Alayhi wa Sallam se (aakhri rawi ko zikr kiye baghair) Mursal-an Riwayat kiya hai ke Hazrat Sayyiduna Abu Saeed Radiyallahu Anhu ko zikr nahi kiya. Is Riwayat ki aur bhi Sanadein hain jo ek dusre ko taqwiyat deti hain.)"}, {"id": 6898, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 33, "arabic": "عَنِ ابْنِ عَبَّاسٍ رَضیَ اللهُ عَنْہُمَا مَا اَنَّ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’لَوْ يُعْطَى النَّاسُ بِدَعْوَاهُمْ لَادَّعٰى رِجَالٌ اَمْوَالَ قَومٍ وَدِمَآءَهُمْ لٰكِنِ الْبَيِّنَةُ عَلَى الْمُدَّعِيْ وَالْيَمِيْنُ عَلٰى مَنْ اَنكَرَ.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ الْبَيْهَقِیُّ وَغَيْرُهٗ هٰكَذَا وَبَعْضُهٗ فِی الصَّحِيْحَيْن)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اگر لوگوں کو ان کے دعوے کے مطابق دے دیا جائے تو لوگ دوسروں کی جان و مال کا دعویٰ کرنے لگیں گے، لیکن دعویٰ کرنے والے کے ذمہ گواہ ہے اور قسم انکار کرنے والے پر ہے۔‘‘\n(سنن الکبری للبيهقی، كتاب الدعوى والبينات، باب البينة على المدعی...الخ، ۱۰/۴۲۷، حدیث: ۲۱۲۰۱ ۔ ابن ماجة، کتاب الاحکام، باب البینة علی المدعی...الخ، ۳/ ۹۶، حدیث:۲۳۲۱ ۔ بخاری، تفسیر سورة ال عمران، باب قولہ تعالی: ان الذین یشترون بعھداللّٰہ، ۴/ ۱۹۰، حدیث: ۴۵۵۲ ۔ مسلم، کتاب الاقضیة، باب الیمین علی مدعی علیہ، ص۹۴۱، حدیث:۱۷۱۱)\n(یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابو بکر احمد بن حسین بن علی بیہقی رحمۃ اللہ علیہ اور دیگر محدثین نے اسی طرح روایت کیا ہے۔ اس کا کچھ حصہ بخاری ومسلم میں بھی ہے۔)", "roman": "Hazrat Sayyiduna Abdullah bin Abbas Radiyallahu Anhuma se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: 'Agar logon ko un ke da'we ke mutabiq de diya jaye to log dusron ki jaan o Maal ka da'wa karne lagen ge, lekin da'wa karne wale ke zimma Gawah hai aur qasam inkar karne wale par hai.' (Sunan-ul-Kubra lil-Baihaqi, Kitaab-ud-Da'wa wal-Bayyinaat, Baab-ul-Bayyinatu alal-mudda'i... al-kh, 10/427, Hadees: 21201. Ibn-e-Majah, Kitaab-ul-Ahkaam, Baab-ul-Bayyinatu alal-mudda'i... al-kh, 3/96, Hadees: 2321. Bukhari, Tafseer-e-Surah Al-Imran, Baab qawlihi Ta'ala: Innal-lazina yashtaruna bi-ahdillahi, 4/190, Hadees: 4552. Muslim, Kitaab-ul-Aqziya, Baab-ul-Yameeni ala mudda'a alayhi, s 941, Hadees: 1711) (Yeh Hadees Hasan hai ise Hazrat Sayyiduna Imam Abu Bakr Ahmad bin Hussain bin Ali Baihaqi Rahmatullah Alayh aur deegar Muhaddiseen ne isi tarah Riwayat kiya hai. Is ka kuch hissa Bukhari o Muslim mein bhi hai.)"}, {"id": 6899, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 34, "arabic": "عَنْ اَبِيْ سَعِيْدِ الْخُدَرِيِّ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُوْلُ: ’’مَنْ رَاٰى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهٖ فَاِنْ لَّمْ يَسْتَطِعْ فَبِلِسَانِهٖ فَاِنْ لَّمْ يَسْتَطِعْ فَبِقَلْبِهٖ وَذٰلِكَ اَضْعَفُ الْاِيْمَانِ.‘‘ (رَوَاهُ مُسْلِمٌ)", "urdu": "حضرت سیِّدُنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم کو ارشاد فرماتے سنا: ’’تم میں سے جو کوئی برا کام دیکھے تو اسے چاہیے کہ اپنےہاتھ سے روک دے، اگر اس کی طاقت نہیں رکھتا تو زبان سے، اگر اس کی بھی طاقت نہیں رکھتا تو دل سے (بُرا جانے) اور یہ ایمان کا کمزور ترین درجہ ہے۔‘‘\n( مسلم، كتاب الايمان، باب بيان کون النھی عن المنكر من الايمان…الخ، ص۴۹، حدیث:۱۷۷)", "roman": "Hazrat Sayyiduna Abu Saeed Khudri Radiyallahu Anhu bayan karte hain ke main ne Rasoolullah Sallallahu Alayhi wa Sallam ko irshad farmate suna: 'Tum mein se jo koi bura kaam dekhe to use chahiye ke apne haath se rok de, agar is ki taqat nahi rakhta to zabaan se, agar is ki bhi taqat nahi rakhta to dil se (bura jaane) aur yeh Imaan ka kamzor tareen darja hai.' (Muslim, Kitaab-ul-Imaan, Baab bayan kawnin-nahyi anil-munkari minal-Imaan... al-kh, s 49, Hadees: 177)"}, {"id": 6900, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 35, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : ’’لَاتَحَاسَدُوْا وَلَاتَنَاجَشُوْا وَلَاتَبَاغَضُوْا وَلَاتَدَابَرُوْا وَلَايَبِعْ بَعْضُكُمْ عَلٰى بَيْعِ بَعْضٍ وَكُوْنُوْا عِبَادَ اللهِ اِخْوَانًا، اَلْمُسْلِمُ اَخُو الْمُسْلِـمِ، لَايَظْلِمُهٗ وَلَايَخْذُلُهٗ وَلَايَكْذِبُهٗ وَلَايَحْقِرُهٗ، اَلتَّقْوٰى هٰهُنَا.‘‘ وَيُشِيْرُ اِلٰى صَدْرِهٖ ثَلَاثَ مَرَّاتٍ. ’’بِحَسْبِ امْرِئٍ مِّنَ الشَّرِ اَن يَّحْقِرَ اَخَاهُ الْمُسْلِمَ، كُلُّ الْمُسْلِـمِ عَلَى الْمُسْلِـمِ حَرَامٌ دَمُهٗ وَمَالُهٗ وَعِرْضُهٗ.‘‘(رَوَاهُ مُسْلِم)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلم نے ارشاد فرمایا: ایک دوسرے سے حسد نہ کرو، صرف قیمت بڑھانے کے لیے بولی نہ لگاؤ، آپس میں بغض نہ رکھو، قطع تعلقی نہ کرو، تم میں سے کوئی دوسرے کے سودے پر سودا نہ کرے، اللہ کے بندو بھائی بھائی ہوجاؤ، ایک مسلمان دوسرے مسلمان کا بھائی ہے کہ نہ اس پر ظلم کرتا ہے، نہ اسے رسواکرتا ہے، نہ اس سے جھوٹ بولتا ہے اور نہ ہی اسے حقیر جانتا ہے۔آپ نے اپنے سینہ مبارک کی طرف اشارہ کرتے ہوئے تین مرتبہ ارشاد فرمایا:تقوی یہاں ہے،کسی شخص کے برا ہونے کے لیے اتنا کافی ہے کہ وہ اپنے مسلمان بھائی کو حقیر سمجھے، ہر مسلمان پر دوسرے مسلمان کا خون، مال اور عزت حرام ہے۔\n(مسلم، كتاب البر والصلة والاٰداب، باب تحريم ظلم المسلم وخذلہ واحتقاره...الخ، ص۱۰۶۴، حدیث:۶۵۴۱)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu bayan karte hain ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: Ek dusre se hasad na karo, Sarf qeemat barhane ke liye boli na lagao, aapas mein bughz na rakho, qata-e-ta'alluqi na karo, tum mein se koi dusre ke saude par sauda na kare, Allah ke bando bhai bhai ho jao, ek Musalman dusre Musalman ka bhai hai ke na is par zulm karta hai, na ise ruswa karta hai, na is se jhoot bolta hai aur na hi ise haqeer janta hai. Aap ne apne seena-e-mubarak ki taraf ishara karte hue teen martaba irshad farmaya: Taqwa yahan hai, kisi Shakhs ke bura hone ke liye itna kaafi hai ke woh apne Musalman bhai ko haqeer samjhe, har Musalman par dusre Musalman ka khoon, Maal aur izzat Haram hai. (Muslim, Kitaab-ul-Birri was-Silati wal-Aadaab, Baab tahreemi zulmil-Muslimi wa khazlihi wahtiqarihi... al-kh, s 1064, Hadees: 6541)"}, {"id": 6901, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 36, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ’’مَنْ نَفَّسَ عَنْ مُّؤمِنٍ كُرْبَةً مِّنْ كُرَبِ الدُّنيَا نَفَّسَ اللهُ عَنْهُ كُرْبَةً مِّنْ كُرَبِ يَوْمِ الْقِيَامَةِ وَمَنْ يَّسَّرَ عَلٰى مُعْسَرٍ يَّسَّرَ اللهُ عَلَيهِ فِي الدُّنْيَا وَالْاٰخِرَةِ وَمَنْ سَتَـرَ مُسلِمًا سَتَـرَهُ اللهُ فِيْ الدُّنْيَا وَالْاٰخِرَةِ وَاللهُ فِيْ عَوْنِ الْعَبْدِ مَا كَانَ الْعَبْدُ فِيْ عَوْنِ اَخِيْهِ وَمَنْ سَلَكَ طَرِيْقًا يَّلْتَمِسُ فِيْهٖ عِلْمًا سَهَّلَ اللهُ لَهٗ بِهٖ طَرِيْقًا اِلَى الْجَنَّةِ وَمَا اجْتَمَعَ قَوْمٌ فِيْ بَيْتٍ مِّنْ بُيُوْتِ اللهِ يَتْلُوْنَ كِتَابَ اللهِ وَيَتَدَارَسُوْنَهٗ بَيْنَهُمْ اِلَّا نَـزَلَتْ عَلَيْهِمُ السَّكِيْنَةُ وَغَشِيَتْهُمُ الرَّحْمَةُ وَحَفَتْهُمُ الْمَلَآئِكَةُ وَذَكَرَهُمُ اللهُ فِيْمَنْ عِنْدَهٗ وَمَنْ بَطَّاَ بِهٖ عَمَلُهٗ لَمْ يُسْرِعْ بِهٖ نَسَبُهٗ.‘‘(رَوَاهُ مُسْلِمٌ بِهٰذَا اللّفْظ)", "urdu": "حضرت سیِّدُنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’جس نے کسی مومن سے دنیا کی کوئی پریشانی دور کی تو اللہ پاک قیامت کے دن کی پریشانیوں میں سےاس کی ایک پریشانی دور فرمائے گااورجس نے کسی تنگ دست پر آسانی کی تو اللہ پاک اس پردنیا و آخرت میں آسانی فرمائے گا اور جس نے کسی مسلمان کی پردہ پوشی کی تو اللہ پاک دنیا و آخرت میں اس کی پردہ پوشی فرمائے گا۔ اللہ پاک اپنے بندے کی مدد فرماتا رہتا ہے جب تک بندہ اپنے بھائی کی مدد کرتا رہتا ہے اور جو شخص علم کی تلاش میں کسی راستے پر چلتا ہے تو اللہ پاک اس کے سبب اس کے لئے جنت کا راستہ آسان فرمادیتا ہے اور جو لوگ اللہ پاک کے گھروں میں سے کسی گھر (یعنی مسجد)میں جمع ہو کر قرآنِ پاک کی تلاوت کرتے اور پڑھتے پڑھاتے ہیں تو ان پر سکینہ نازل ہوتا ہے، رحمت انہیں ڈھانپ لیتی ہے اور فرشتے انہیں گھیرلیتے ہیں اور اللہ پاک اپنی بارگاہ میں موجود فرشتوں کے سامنے ان کا تذکرہ فرماتا ہےاور جس کا عمل اسے پیچھے کردے تو اُس کا نسب اسے آگے نہیں بڑھا سکتا۔‘‘\n( مسلم، كتاب الذكر والدعاء والتوبة...الخ، باب فضل الاجتماع على تلاوة القراٰن وعلى الذكر، ص۱۱۱۰، حدیث:۶۸۵۳)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasoolullah Sallallahu Alayhi wa Sallam ne irshad farmaya: 'Jis ne kisi Momin se duniya ki koi pareshani door ki to Allah Paak Qayamat ke din ki pareshaniyon mein se us ki ek pareshani door farmaye ga aur jis ne kisi tang dast par aasani ki to Allah Paak us par duniya o Aakhirat mein aasani farmaye ga aur jis ne kisi Musalman ki Pardah poshi ki to Allah Paak duniya o Aakhirat mein us ki Pardah poshi farmaye ga. Allah Paak apne bande ki madad farmata rehta hai jab tak banda apne bhai ki madad karta rehta hai aur jo Shakhs Ilm ki talash mein kisi raaste par chalta hai to Allah Paak us ke sabab us ke liye Jannat ka raasta aasaan farma deta hai aur jo log Allah Paak ke gharon mein se kisi ghar (yani Masjid) mein jama ho kar Quraan-e-Paak ki tilawat karte aur parhte parhate hain to un par Saki na nazil hota hai, Rahmat unhein dhanp leti hai aur farishtay unhein gher lete hain aur Allah Paak apni bargah mein majood farishton ke samne un ka tazkira farmata hai aur jis ka amal use peeche kar de to us ka Nasab use aage nahi barha sakta.' (Muslim, Kitaab-uz-Zikri wad-Du'a wat-Tawbati... al-kh, Baab fazlil-ijtima'i ala tilawatil-Quraani wa ala-Zikr, s 1110, Hadees: 6853)"}, {"id": 6902, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 37, "arabic": "عَن ابْنِ عَبَّاسٍ رَضیَ اللهُ عَنْہُمَا مَا عَنِ رَسُوْلِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيْمَا يَرْوِيْهِ عَنْ رَبِّهٖ تَبَارَكَ وَتَعَالٰى قَالَ:’’اِنَّ اللهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذٰلِكَ؛ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَـبَهَا اللهُ عِنْدَهٗ حَسَنَةً كَامِلَةً وَّاِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَـبَهَا اللهُ عِنْدَهٗ عَشْرَ حَسَنَاتٍ اِلٰى سَبْعِمائَةِ ضِعْفٍ اِلٰى اَضْعَافٍ كَثِيْرَةٍ وَاِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَـبَهَا اللهُ عِنْدَهٗ حَسَنَةً كَامِلَةً وَّاِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَـبَهَا اللهُ سَيِّئَةً وَّاحِدَةً.‘‘ (رَوَاهُ الْبُخَارِیُّ وَمُسْلِمٌ فِیْ صَحِيْحَيْهِمَا بِهٰذِهِ الحُرُوْف)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما حضور نبی پاک صلّی اللہ علیہ واٰلہٖ وسلّم سے روایت کرتے ہیں اور یہ ان روایات میں سےہے جو آپ صلّی اللہ علیہ واٰلہٖ وسلّم اپنے رب سے روایت کرتے ہیں (یعنی حدیث قدسی ہے)، ارشاد فرمایا: ’’بے شک اللہ پاک نے اچھائیاں اور برائیاں لکھ دیں اور انہیں واضح فرما دیا، لہٰذا جو شخص کسی بھلائی کا ارادہ کرے لیکن عمل نہ کر پائے تو اللہ پاک اس کے لئے اپنے پاس ایک کامل نیکی کا ثواب لکھ دیتا ہے اور اگروہ کسی نیکی کاارادہ کرے اور عمل بھی کر لے تو اللہ کریم اپنے پاس اس نیکی کا ثواب 10سے 700 گنا بلکہ اس سے بھی زیادہ تک لکھ دیتا ہے اور اگر بندہ کسی گناہ کا ارادہ کرے مگر گناہ نہ کرے تو اللہ پاک اس کےلئے اپنے پاس ایک کامل نیکی کاثواب لکھ دیتا ہےاور اگر وہ گناہ کا ارادہ کر کے اسے کر گزرے تو اللہ پاک اس کے لئے صرف ایک گناہ لکھتا ہے۔‘‘(بخاری، كتاب الرقاق، باب من همّ بحسنة او بسيئة، ۴/ ۲۴۴، حدیث:۶۴۹۱۔ مسلم، کتاب الایمان، باب اذا ھم العبد بحسنة کتبت...الخ، ۷۴، حدیث:۳۳۸)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عبداللہ محمد بن اسماعیل بخاری اور حضرت سیِّدُنا ابوحسین امام مسلم بن حجاج رحمۃ اللہ علیہما نے اپنی اپنی صحیح (بخاری ومسلم) میں انہی الفاظ میں روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abdullah Bin Abbas Radiyallahu Anhuma, Rasoolullah Sallallahu Alaihi Wasallam se riwayat karte hain aur yeh un riwayaat mein se hai jo Aap Sallallahu Alaihi Wasallam apne Rabb se riwayat karte hain (yaani Hadees-e-Qudsi hai), irshad farmaya: ''Beshak Allah Paak ne achhaiyan aur buraiyan likh di aur unhein wazeh farma diya, lehaza jo Shakhs kisi bhalai ka irada kare lekin amal na kar paye toh Allah Paak us ke liye apne paas ek kaamil neki ka sawab likh deta hai aur agar woh kisi neki ka irada kare aur amal bhi kar le toh Allah Kareem apne paas us neki ka sawab 10 se 700 guna balkay us se bhi zyada tak likh deta hai aur agar banda kisi gunah ka irada kare magar gunah na kare toh Allah Paak us ke liye apne paas ek kaamil neki ka sawab likh deta hai aur agar woh gunah ka irada kar ke usay kar guzre toh Allah Paak us ke liye sirf ek gunah likhta hai.'' (Bukhari, Kitaab-ur-Riqaq, Baab Man Hamma Bi-Hasanatin Aw Bi-Sayyi'atin, 4/244, Hadees: 6491. Muslim, Kitaab-ul-Imaan, Baab Iza Hammal Abdu Bi-Hasanatin Kutibat... Al-Kh, 74, Hadees: 338). (Is Hadees ko Hazrat Sayyiduna Imam Abu Abdullah Muhammad Bin Ismail Bukhari aur Hazrat Sayyiduna Abu Hussain Imam Muslim Bin Hajjaj Rahmatullah Alayhima ne apni apni Saheeh (Bukhari-o-Muslim) mein inhi alfaaz mein riwayat kiya hai.)"}, {"id": 6903, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 38, "arabic": "عَنْ اَبِيْ هُرَيْرَةَ رَضيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : اِنَّ اللهَ تَعَالٰى قَالَ: ’’مَنْ عَادَى لِيْ وَلِيًّا فَقَدْ اٰذَنْتُهٗ بِالْحَرْبِ. وَمَا تَقَرَّبَ اِلَيَّ عَبْدِيْ بِشَيْءٍ اَحَبَّ اِلَيَّ مِمَّا افْتَرَضْتُ عَلَيْهِ. وَمَا يَزَالُ عَبْدِيْ يَتَقَرَّبُ اِلَيَّ بِالنَّوَافِلِ حَتّٰى اُحِبَّهٗ، فَاِذَا اَحْبَبْتُهٗ كُنْتُ سَمْعَهُ الَّذِيْ يَسْمَعُ بِهٖ وَبَصَرَهُ الَّذِيْ يُبْصِرُ بِهٖ وَيَدَهُ الَّتِيْ يَبْطِشُ بِهَا وَرِجْلَهُ الَّتِيْ يَمْشِيْ بِهَا. وَاِنْ سَاَلَنِيْ اَعْطَیْتُہٗ وَلَئِنِ اسْتَعَاذَنِيْ لَاُعِيْذَنَّهٗ.‘‘ (رَوَاهُ الْبُخَارِیُّ)", "urdu": "حضرت سیِّدُنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں: حضور نبی کریم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا کہ اللہ پاک کا فرمان ہے: ’’جس نے میرے کسی ولی سے دشمنی کی تو میں اس کے ساتھ جنگ کا اعلان کرتا ہوں۔ میرا بندہ جن چیزوں سے میرا قُرب حاصل کرتا ہے ان میں فرائض مجھے سب سے زیادہ محبوب ہیں اور نوافل کے ذریعہ بندہ میرے قریب ہوتا رہتا ہے یہاں تک کہ میں اسے اپنا محبوب بنا لیتا ہوں تو جب میں اسے اپنا محبوب بنا لیتا ہوں تو اس کے کان ہو جاتا ہوں جن سے وہ سنتا ہے، اس کی آنکھ ہو جاتا ہوں جن سے وہ دیکھتا ہے، اس کے ہاتھ ہو جاتا ہوں جن سے وہ پکڑتا ہے، اس کے پاؤں ہو جاتا ہوں جن سے وہ چلتا ہے، اگروہ مجھ سے مانگے تو ضرور اسے دوں گا اور اگر وہ مجھ سے پناہ طلب کرے تو میں ضرور اسے پناہ دوں گا۔‘‘ ( بخاری، كتاب الرقاق، باب التواضع، ۴/ ۲۴۸، حدیث:۶۵۰۲)", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu bayan karte hain: Rasoolullah Sallallahu Alaihi Wasallam ne irshad farmaya ke Allah Paak ka farman hai: ''Jis ne mere kisi Wali se dushmani ki toh main us ke saath jang ka elaan karta hoon. Mera banda jin cheezon se mera qurb hasil karta hai un mein faraiz mujhe sab se zyada mehboob hain aur nawafil ke zariye banda mere qareeb hota rehta hai yahan tak ke main usay apna mehboob bana leta hoon toh jab main usay apna mehboob bana leta hoon toh us ke kaan ho jata hoon jin se woh sunta hai, us ki aankh ho jata hoon jin se woh dekhta hai, us ke haath ho jata hoon jin se woh pakarta hai, us ke paon ho jata hoon jin se woh chalta hai, agar woh mujh se mange toh zaroor usay doon ga aur agar woh mujh se panah talab kare toh main zaroor usay panah doon ga.'' (Bukhari, Kitaab-ur-Riqaq, Baab-ut-Tawazu, 4/248, Hadees: 6502)"}, {"id": 6904, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 39, "arabic": "عَنِ ابْنِ عَبَّاسٍ رَضيَ اللهُ عَنْهُ مَا اَنَّ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَال: ’’اِنَّ اللهَ تَجَاوَزَ لِيْ عَنْ اُمَّتِيْ اَلْخَطَاَ وَالنِّسْيَانَ وَمَا اسْتُكْرِهُوْا عَلَيْهِ.‘‘ (حَدِيْثٌ حَسَنٌ رَوَاهُ ابْنُ مَاجَه والْبَيْهَقِیُّ وَغَيْرُهُمَا)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ اللہ پاک کے آخری نبی، محمد عربی صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’اللہ پاک نے میری وجہ سے میری امت کی غلطی، بھول اور جس پر وہ مجبور کئے جائیں ان گناہوں کو معاف فرمادیا ہے۔‘‘(ابن ماجہ، كتاب الطلاق، باب طلاق المكره والناسی، ۲/ ۵۱۳، حدیث:۲۰۴۵۔ سنن الکبری للبیھقی، کتاب الخلع والطلاق، باب ماجاء فی طلاق المکرہ...الخ، ۷/ ۵۸۴، حدیث:۱۵۰۹۶، ’’ان اللّٰہ تجاوز لی‘‘ بدلہ ’’وضع اللّٰہ‘‘)\n (یہ حدیث حسن ہے اسے حضرت سیِّدُنا امام ابن ماجہ، حضرت سیِّدُنا امام بیہقی رحمۃ اللہ علیہما اور دیگر محدثین نے روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abdullah Bin Abbas Radiyallahu Anhuma se riwayat hai ke Allah Paak ke aakhri Nabi, Muhammad Arabi Sallallahu Alaihi Wasallam ne irshad farmaya: ''Allah Paak ne meri wajah se meri ummat ki ghalti, bhool aur jis par woh majboor kiye jayen un gunahon ko maaf farma diya hai.'' (Ibn Majah, Kitaab-ut-Talaq, Baab Talaq-ul-Mukrah wan-Naasi, 2/513, Hadees: 2045. Sunan-ul-Kubra lil-Baihaqi, Kitaab-ul-Khula wat-Talaq, Baab Ma Ja'a Fi Talaq-il-Mukrah... Al-Kh, 7/584, Hadees: 15096, ''Innallaha tajawaza li'' badla ''Wada'allahu''). (Yeh Hadees Hasan hai, isay Hazrat Sayyiduna Imam Ibn Majah, Hazrat Sayyiduna Imam Baihaqi Rahmatullah Alayhima aur deegar Muhaddiseen ne riwayat kiya hai.)"}, {"id": 6905, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 40, "arabic": "عَنِ ابْنِ عُمَرَ رَضيَ اللهُ عَنْهُ مَا قَالَ: اَخَذَ رَسُوْلُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمنْكَبيَّ. فَقَالَ: ’’ كُنْ فِي الدُّنْيَا كَاَنَّكَ غَرِيْبٌ اَوْ عَابِرُ سَبِيْلٍ.‘‘ وَكَانَ ابْنُ عُمَرَ رَضيَ اللهُ عَنْهُ مَا يَقُوْلُ: اِذَا اَمْسَيْتَ فَلَاتَنْتَظِرِ الصَّبَاحَ وَاِذَا اَصْبَحْتَ فَلَاتَنْتَظِرِ الْمَسَاءَ. وَخُذْ مِنْ صِحَّتِكَ لِمَرَضِكَ وَمِنْ حَيَاتِكَ لِمَوْتِكَ. (رَوَاهُ الْبُخَارِیُّ)", "urdu": "حضرت سیِّدُنا عبد اللہ بن عُمَر رضی اللہ عنہما بیان کرتے ہیں کہ ایک مرتبہ رسولُ اللہ صلّی اللہ علیہ واٰلہٖ وسلّم نے میرے دونوں کاندھوں کو ہاتھوں میں لے کر ارشاد فرمایا: ’’دنیا میں پر دیسی یا راہ گزر (یعنی آبائی وطن سے دور رہنے والے یامسافر)کی طرح رہو۔‘‘ حضرت سیِّدُنا عبد اللہ بن عُمَر رضی اللہ عنہما فرمایا کرتے تھے: جب تم شام کرو تو صبح کا انتظار مت کرو اور جب صبح کرو تو شام کا انتظار مت کرو، اپنی تندرستی میں بیماری کا حصہ لے لو اور اپنی زندگی میں موت کی تیاری کر لو۔\n( بخاری، كتاب الرقاق، باب قول النبی: كن فی الدنيا كانك غريب...الخ، ۴/ ۲۲۳، حدیث:۶۴۱۶)", "roman": "Hazrat Sayyiduna Abdullah Bin Umar Radiyallahu Anhuma bayan karte hain ke ek martaba Rasoolullah Sallallahu Alaihi Wasallam ne mere dono kandhon ko hathon mein le kar irshad farmaya: ''Duniya mein pardesi ya raah-guzar (yaani aabai watan se door rehne wale ya musafir) ki tarah raho.'' Hazrat Sayyiduna Abdullah Bin Umar Radiyallahu Anhuma farmaya karte thay: Jab tum shaam karo toh subah ka intezar mat karo aur jab subah karo toh shaam ka intezar mat karo, apni tandurusti mein bimari ka hissa le lo aur apni Zindagi mein maut ki tayyari kar lo. (Bukhari, Kitaab-ur-Riqaq, Baab Qaul-in-Nabi: Kun Fid-Dunya Ka'annaka Ghareeb... Al-Kh, 4/223, Hadees: 6416)"}, {"id": 6906, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 41, "arabic": "عَنْ اَبِيْ مُحَمَّدٍ عَبْدِ اللهِ بِنِ عمْرِو بْنِ الْعَاصِ رَضيَ اللهُ عَنْهُ مَا قَالَ: قَالَ رَسُولُ اللهِ: ’’لَا يُؤْمِنُ اَحَدُكُمْ حَتّٰى يَكُوْنَ هَوَاهُ تَبَعًا لِّمَا جِئْتُ بِهٖ.‘‘ (حَدِيْثٌ صَحِيْحٌ رَوَيْنَاهُ فِیْ كِتَابِ الْحُجَّةِ بِاِسْنَادٍ صَحِيْحٍ)", "urdu": "حضرت سیِّدُنا ابو محمد عبداللہ بن عَمْرو بن عاص رضی اللہ عنہما بیان کرتے ہیں کہ حضور نبی اکرم صلّی اللہ علیہ واٰلہٖ وسلّم نے ارشاد فرمایا: ’’تم میں سے کوئی شخص اس وقت تک کامل مومن نہيں ہوسکتا جب تک اس کی خواہشات میرے لائے ہوئے احکامات کے تابع نہ ہوجائیں۔‘‘ (نوادر الاصول فی احاديث الرسول، الاصل الثامن والسبعون والمائتان، ۶/ ۴۵۳)\n (یہ حدیث صحیح ہے اسے (حضرت سیِّدُنا امام محمد بن طاہر مقدسی رحمۃ اللہ علیہ نے) کتاب الحجۃ میں صحیح سند کے ساتھ روایت کیا ہے۔)", "roman": "Hazrat Sayyiduna Abu Muhammad Abdullah Bin Amr Bin Aas Radiyallahu Anhuma bayan karte hain ke Rasoolullah Sallallahu Alaihi Wasallam ne irshad farmaya: ''Tum mein se koi Shakhs us waqt tak kaamil momin nahin ho sakta jab tak us ki khwahishat mere laye hue ahkamaat ke tabe na ho jayen.'' (Nawadir-ul-Usool Fi Ahadis-ir-Rasool, Al-Asl-us-Samin-wal-Sab'oon wal-Mi'atain, 6/453). (Yeh Hadees Saheeh hai, isay (Hazrat Sayyiduna Imam Muhammad Bin Tahir Maqdisi Rahmatullah Alayh ne) Kitaab-ul-Hujjah mein Saheeh Sanad ke saath riwayat kiya hai.)"}, {"id": 6907, "bookId": 13, "bookName": "شرح اربعین نوویہ(اردو)", "volId": 17, "chapterId": 0, "chapterTitle": "", "hadithNo": 42, "arabic": "عَنْ اَنَسٍ رَضيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُوْلَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: قَالَ اللهُ تَعَالٰی: ’’يَا ابْنَ اٰدَمَ اِنَّكَ مَا دَعَوْتَنِيْ وَرَجَوْتَنِيْ غَفَرْتُ لَكَ عَلٰى مَا كَانَ مِنْكَ وَلَا اُبَالِيْ. يَا ابْنَ اٰدَمَ لَوْ بَلَغَتْ ذُنُوْبُكَ عَنَانَ السَّمَآءِ ثُمَّ اسْتَغْفَرْتَنِيْ غَفَرْتُ لَكَ. يَا ابْنَ اٰدَمَ اِنَّكَ لَوْ اَتَيْتَنِيْ بِقِرَابِ الْاَرْضِ خَطَايَا ثُمَّ لَقِيْتَنِيْ لَاتُشْرِكُ بِيْ شَيْئًا لَّاَتَيْتُكَ بِقِرَابِهَا مَغفِرَةً.‘‘\n(رَوَاهُ التِّرْمَذِیُّ وَقَالَ: حَدِيْثٌ حَسَنٌ)", "urdu": "حضرت سیِّدُنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں: میں نے رَسُولُ الله صلّی اللہ علیہ واٰلہٖ وسلّم كو ارشاد فرماتے سنا کہ الله پاک ارشاد فرماتا ہے: ’’اے ابن آدم! تو مجھ سے جو بھی دعا مانگتا ہے اورمجھ سے امید بھی رکھتا ہے تو میں تیری نافرمانیوں کے باجود تجھے بخش دیتا ہوں اور مجھے اس کی کوئی پرواہ نہیں۔ اے ابن آدم! اگر تیرے گناہ آسمان کی بلندیوں کو پہنچ جائیں پھرتو مجھ سے بخشش طلب کرے تو میں تجھے بخش دوں گا۔ اے ابن آدم! اگرتو میرے پاس زمین بھر خطائیں لے کرآئے مگر مجھ سے اس حال میں ملے کہ تو نے کسی کو میرا شریک نہ ٹھہرایا ہو تو میں تجھے زمین بھر بخشش عطا کروں گا۔‘‘ \n(ترمذی، كتاب الدعوات عن رسول الله صلى الله عليہ وسلم، باب فی فضل التوبة والاستغفار...الخ، ۵/ ۳۱۹، حدیث:۳۵۵۱)\n (اس حدیث کو حضرت سیِّدُنا امام ابو عیسیٰ محمد بن عیسیٰ ترمذی رحمۃ اللہ علیہ نے روایت کیا اور فرمایا: یہ حدیث حسن ہے۔)", "roman": "Hazrat Sayyiduna Anas Bin Malik Radiyallahu Anhu bayan karte hain: Main ne Rasoolullah Sallallahu Alaihi Wasallam ko irshad farmate suna ke Allah Paak irshad farmata hai: ''Aye Ibn-e-Aadam! Tu mujh se jo bhi Dua mangta hai aur mujh se umeed bhi rakhta hai toh main teri nafarmaniyon ke bawajood tujhe bakhsh deta hoon aur mujhe is ki koi parwah nahin. Aye Ibn-e-Aadam! Agar tere gunah aasman ki bulandiyon ko pahunch jayen phir tu mujh se bakhshish talab kare toh main tujhe bakhsh doon ga. Aye Ibn-e-Aadam! Agar tu mere paas Zameen bhar khatayen le kar aaye magar mujh se is haal mein mile ke tu ne kisi ko mera shareek na thehraya ho toh main tujhe Zameen bhar bakhshish ata karoon ga.'' (Tirmidhi, Kitaab-ud-Da'waat An Rasoolillah Sallallahu Alaihi Wasallam, Baab Fi Fazl-it-Tawbati wal-Istighfaar... Al-Kh, 5/319, Hadees: 3551). (Is Hadees ko Hazrat Sayyiduna Imam Abu Isa Muhammad Bin Isa Tirmidhi Rahmatullah Alayh ne riwayat kiya aur farmaya: Yeh Hadees Hasan hai.)"}];
